lectures.body:
Если функция выполняет одновременно несколько задач, то ее очень сложно поддерживать, сложнее читать и ориентироваться к ней. Например, если функция выполняет выделение и очистку памяти и при этом также выполняет некоторые операции, ради которых эта функция и была определена, то можно упустить логику очистки памяти - попытаться освободить одну и ту же память в нескольких местах или вовсе забыть освободить. И решением в данном случае будет разбивка функции на отдельные функции, каждая из которых выполняет одну обязанность или несут одну ответственность.

Рассмотрим небольшой пример, в котором выполняется поиск в файле некоторого слова:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void find(char*, char*, size_t);

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
    find(filename, word, size);
}

void find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;

    if(file_name && word && (word_size>0)) // если указано имя файла и слово для поиска и его размер больше 0
    {
        if((file_pointer=fopen(file_name, "r")))    // если файл открыт для чтения
        {
            if((buffer=malloc(word_size)))      // если память выделена
            {
                int found = 0; // индикатор, что слово найдено
                // собственно действия функции - поиск ключевых слов в файле
                while(fgets(buffer, word_size, file_pointer))
                {
                    if(strcmp(word, buffer)==0)
                    {
                        found = 1;
                        break;
                    }
                }
                if(found) {
                    printf("Success! Text found!\n");
                }
                else{
                    printf("Text not found...\n");
                }
                free(buffer);
            }
            else{
                printf("Error! Unable to locate memory!\n");
            }
            fclose(file_pointer);
        }
        else{
            printf("Error! Unable to open file!\n");
        }
    }
    else
    {
        printf("Error! Params are incorrect!\n");
    }
}
```

Здесь основые действия выполняются в функции `find()`. Она получает имя файла для считывания, искомое слово и размер слова. Вначале проверяется корректность входных параметров. В идеале, конечно, для каждого параметра можно было сделать отдельную проверку и выводить на консоль специфичное для каждого параметра сообщение об ошибки. Но чтобы упростить пример, в данном случае все три параметра проверяются разом.

После проверки параметров открываем файл на чтение и проверяем, что он открыт.

Затем выделяем память для хранения считанных из файла данных и проверяем, что память выделена.

Далее идет собственно считывание файла и проверка, что считанное слово аналогично искомому. И собственно вывод результата.

И здесь мы сталкиваемся с каскадом ifов. В итоге такую функцию сложнее читать и поддерживать. И такая функция - очень хороший пример для разбивки на отдельные функции.

Прежде всего надо выделить функциональные блоки, которые можно отделить от остального функционала. Одним из индикаторов, что функцию надо разделить, является сочетание управление ресурсами и собственно основного кода функции, ради которого она и задумывалась. В этом случае нередко управление ресурсами выносится в одну функцию, которая выступает оберткой, типа следующего:

```c
// функция-обертка, которая управляет ресурсами
void someFunction()
{
    char* buffer = malloc(SOME_SIZE);
    if(buffer)
    {
        // вызов основной функции
        mainFunctionality(buffer);
    }
    free(buffer);
}
// основная функция
void mainFunctionality()
{
    // основные действия
}
```

Подобный механизм иногда называются **Function Wrapper**. Так, изменим программу, отделив управление ресурсами от собственно поиска в файле:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void find(char*, char*, size_t);
void find_word(char*, char*, size_t, FILE*);

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);

    find(filename, word, size);
}

void find_word(char* buffer, char* word, size_t word_size, FILE* file_pointer){
    int found = 0; // индикатор, что слово найдено
    while(fgets(buffer, word_size, file_pointer))
    {
        if(strcmp(word, buffer)==0)
        {
            found = 1;
            break;
        }
    }
    if(found) 
    {
        printf("Success! Word found!\n");
    }
    else
    {
        printf("Word not found...\n");
    }
}

void find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;

    if(file_name && word && (word_size>0)) // если указано имя файла и слово для поиска и его размер больше 0
    {
        if((file_pointer=fopen(file_name, "r")))    // если файл открыт для чтения
        {
            if((buffer=malloc(word_size)))      // если память выделена
            {
                // собственно поиск слова в файле
                find_word(buffer, word, word_size, file_pointer);
                free(buffer);
            }
            else
            {
                printf("Error! Unable to locate memory!\n");
            }
            fclose(file_pointer);
        }
        else{
            printf("Error! Unable to open file!\n");
        }
    }
    else{
        printf("Error! Params are incorrect!\n");
    }
}
```

Теперь поиск вынесен в функцию find_word(), которая вызывается в функции find. Хотя данная программа не идеальна, но нам уже проще управлять по отдельности как выделением-освобождением ресурсов, так и поиском в файле. И при необходимости мы можем пойти дальше. Например, вынести отображение результатов поиска в отдельную функцию и т.д. Или избавиться от многочисленных else-выражений и вынести обработку ошибок в отдельную функцию:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum{
    WORD_FOUND,
    WORD_NOTFOUND,
    PARAMS_ERROR,
    MEMORY_ERROR,
    FILE_ERROR
} status;

void find(char*, char*, size_t);
status find_word(char*, char*, size_t, FILE*);
void process_result(status);

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);

    find(filename, word, size);
}

status find_word(char* buffer, char* word, size_t word_size, FILE* file_pointer)
{
    while(fgets(buffer, word_size, file_pointer))
    {
        if(strcmp(word, buffer)==0)
        {
            return WORD_FOUND;
        }
    }
    return WORD_NOTFOUND;
}


void find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;

    status status_code = PARAMS_ERROR;  // если некорректные параметры
    if(file_name && word && (word_size>0)) // если указано имя файла и слово для поиска и его размер больше 0
    {
        status_code = FILE_ERROR;       // если ошибка при открытии файла
        if((file_pointer=fopen(file_name, "r")))    // если файл открыт для чтения
        {
            status_code = MEMORY_ERROR;         // если ошибка при выделении памяти
            if((buffer=malloc(word_size))) 
            {
                // получаем, найдено ли слово или нет
                status_code = find_word(buffer, word, word_size, file_pointer);
                free(buffer);
            }
            fclose(file_pointer);
        }
    }
    process_result(status_code);  // выводим результат
}

void process_result(status status_code)
{
    switch(status_code)
    {
        case WORD_FOUND:
            printf("Success! Word found!\n");
            break;
        case WORD_NOTFOUND:
            printf("Word not found...\n");
            break;
        case PARAMS_ERROR:
            printf("Error! Params are incorrect!\n");
            break;
        case MEMORY_ERROR:
            printf("Error! Unable to locate memory!\n");
            break;
        case FILE_ERROR:
            printf("Error! Unable to open file!\n");
            break;
    }
}
```

В данном случае для хранения результата определено перечисление status с 5-ю возможными состояниями. В функции find и find_word в зависимости от условий устанавливаем результат и с помощью дополнительной функции process_result выводим то или иное сообщение.

Нередко выполнение функции зависит от некоторых предусловий. В качестве предусловий может выступать контекст, в котором запускается функция. В частности, это могут быть значения параметров или каких-то глобальных переменных. Соответственно проверка предусловий может быть очень важна, поскольку если предусловия не соблюдаются, то выполнение каких-то отдельных моментов функции или вообще всей функции не имеет смысла. Однако проблема частно заключается в том, что проверка предусловий смешивается с основным функционалом, что усложняем чтение и поддержку функции.

Общий механизм при работе с предусловиями состоит в их проверке в начале функции и немедленный выход из функции, если предусловия не соблюдаются, наподобие следующего:

```c
void someFunction(char* user_input)
{
  if(user_input == NULL)
  {
    return;
  }
  operateOnData(user_input);
}
```

Подобный паттерн нередко называют **Guard Clause**. Применим его. И сначала рассмотрим следующую программу:

```c
#include <stdio.h>

void writeTextToFile(char*, char*);

int main(void){
    char* filename ="test.txt";
    char* text = "hello";
    writeTextToFile(filename, text);
}

void writeTextToFile(char* file_name, char* text)
{
    FILE* file_pointer = 0;

    if(file_name) // если имя файла указано
    {
        // открываем файл
        if((file_pointer=fopen(file_name, "w")))    // если файл открыт
        { 
            if(text)    // если валидный текст
            {
                // запись в файл
                if(fputs(text, file_pointer)!=EOF)
                {
                    printf("Success! Text has been written to the file!\n");
                }
            }    
            else 
            {
                printf("Error! Text is incorrect!\n");
            }    
            // закрываем файл
            fclose(file_pointer);
        }
        else
        {
            printf("Error! Unable to open file!\n");
        }
    }
    else
    {
        printf("Error! File name is incorrect!\n");
    }
}
```

Функция `writeTextToFile()` записывает в файл строку. Название файла и записываемая строка передаются через параметры. То есть названия файла и записываемый текст формируют предусловия, от которых зависит выполнение функции. А именно и название файла, и текст не должны быть равны NULL. И функция проверяет эти предусловия. Но если мы взглянем на каскад ifов, то увидим, что проверка предусловий смешивается с основной логикой функции. Более того корректность зависиываемого текста вообще проверяется после открытия файла.

Теперь определим проверку предусловий отдельно:

```c
#include <stdio.h>

void writeTextToFile(char*, char*);

int main(void){
    char* filename ="test.txt";
    char* text = "hello";
    writeTextToFile(filename, text);
}

void writeTextToFile(char* file_name, char* text)
{
    FILE* file_pointer = 0;

    // проверка предусловий 
    if(!file_name==NULL) // если имя файла не указано, выход из функции
    {
        printf("Error! File name is incorrect!\n");
        return;
    }
    if(text == NULL)    // если текст не указан
    {
        printf("Error! Text is incorrect!\n");
        return;
    }    
    // открываем файл
    if((file_pointer=fopen(file_name, "w")))    // если файл открыт
    { 
        // запись в файл
        if(fputs(text, file_pointer)!=EOF)
        {
            printf("Success! Text has been written to the file!\n");
        }   
        // закрываем файл
        fclose(file_pointer);
    }
    else
    {
        printf("Error! Unable to open file!\n");
    }
}
```

Теперь вначале функции проверяются предусловия, и если они не соблюдаются, происходит выход. Таким образом, мы избавились от глубокой вложенности ifов, а предусловиями и основной логикой стало проще управлять.

Но мы можем пойти дальше. На уровне основной части функции также есть предусловие - открыт файл или нет. Мы также можем подобным образом проверять предусловия к отдельным функциональным блокам функции:

```c
#include <stdio.h>

void writeTextToFile(char*, char*);

int main(void){
    char* filename ="test.txt";
    char* text = "hello 2";
    writeTextToFile(filename, text);
}

void writeTextToFile(char* file_name, char* text)
{
    // проверка предусловий 
    if(file_name==NULL) // если имя файла не указано, выход из функции
    {
        printf("Error! File name is incorrect!\n");
        return;
    }
    if(text == NULL)    // если текст не указан
    {
        printf("Error! Text is incorrect!\n");
        return;
    }    
    // открываем файл
    FILE* file_pointer=fopen(file_name, "w");
    if(file_pointer == NULL)    // если открытие файла прошло неудачно, выход из функции открыт
    { 
        printf("Error! Unable to open file!\n");
        return;
    }
    // запись в файл
    if(fputs(text, file_pointer)!=EOF)
    {
        printf("Success! Text has been written to the file!\n");
    }   
    // закрываем файл
    fclose(file_pointer);
}
```

Иногда ошибки, возникающие в процессе работы программы, могут быть очень критичными для работы приложения, а их обработка может быть слишком сложной и требовать много кода. Но при этом подобные ошибки могут быть очень редки, веорятность, что они произойдут в программе, очень низка. Соответственно возникает вопрос, определять ли дополнительный код для обработки ошибки, которая довольна критична, но при этом ее вероятность довольно низка, либо поступить как-то по другому. Особенно учитывая, что любой дополнительный код в принципе усложняет программу и снижает ее читабельность.

Одним из выходов из подобной ситуации является прекращение работы программы при возникновении критичной ошибки. Для этого в языке С может применяться функция **assert()**. Например:

```c
void someFunc()
{
    assert(checkСonditions() && "Error! Conditions are incorrect");
    // основной код
}
```

В данном коде **assert()** с помощью некоторой функции `checkСonditions()` проверяет некоторые условия, и если они не выполняются, **assert()** выводит в стандартный поток ошибок **stderr** сообщение "Error! Conditions are incorrect". И после этого выполнение программы прерывается.

Подобный способ довольно прост. В частности, его можно применять при проверки предусловий, например, на проверку параметров на NULL. Подобный паттерн иногда называют **Assertion Context**

Например, возьмем следующюю программу:

```c
#include <stdio.h>

void writeTextToFile(char*, char*);

int main(void){
    char* filename = "test.txt";
    char* text = "Hello enoobis.ru";
    writeTextToFile(filename, text);
}

void writeTextToFile(char* file_name, char* text)
{
    // проверка предусловий 
    if(file_name==NULL) // если имя файла не указано, выход из функции
    {
        printf("Error! File name is incorrect!\n");
        return;
    }
    if(text == NULL)    // если текст не указан
    {
        printf("Error! Text is incorrect!\n");
        return;
    }

    // открываем файл
    FILE* file_pointer=fopen(file_name, "w");
    if(file_pointer == NULL)    // если открытие файла прошло неудачно, выход из функции открыт
    { 
        printf("Error! Unable to open file!\n");
        return;
    }
    // запись в файл
    if(fputs(text, file_pointer)!=EOF)
    {
        printf("Success! Text has been written to the file!\n");
    }   
    // закрываем файл
    fclose(file_pointer);
}
```

Здесь функция `writeTextToFile()` принимает некоторый текст и записывает его в файл, который также передается через параметр. В начале функции параметры функции проверяются на значение NULL. И в случае, если хотя бы один параметр равен NULL, функция завершает свою работу. Теперь применим **assert**:

```c
#include <stdio.h>
#include <assert.h>>    // для функции assert

void writeTextToFile(char*, char*);

int main(void){
    char* filename = "test.txt";
    char* text = "Hello enoobis.ru";
    writeTextToFile(filename, text);
}

void writeTextToFile(char* file_name, char* text)
{
    // проверка предусловий 
    assert(file_name!=NULL && "Error! File name is incorrect!\n"); // если имя файла не указано, выход из функции
    assert(text != NULL && "Error! Text is incorrect!\n");    // если текст не указан

    // открываем файл
    FILE* file_pointer=fopen(file_name, "w");
    if(file_pointer == NULL)    // если открытие файла прошло неудачно, выход из функции открыт
    { 
        printf("Error! Unable to open file!\n");
        return;
    }
    // запись в файл
    if(fputs(text, file_pointer)!=EOF)
    {
        printf("Success! Text has been written to the file!\n");
    }   
    // закрываем файл
    fclose(file_pointer);
}
```

Таким образом, если выполняются условия `file_name!=NULL` и `text != NULL`, то функция продолжает свою работу - записывает строку в файл. Если хотя бы одно из условий не выполняется, то функция завершает работу, а на консоль выводится сообщение. Например, если file_name = 0, выводится сообщение следующего типа:

```bash
Assertion failed: file_name!=NULL && "Error! File name is incorrect!\n", file app.c, line 15
```

Функция, которая использует множество ресурсов и вынуждена выделять и осовобождать для них память, может для управления ресурсами и обработки ошибок применять вложенные конструкции if. В подобных случаях обычно выделение памяти для одного ресурса зависит от того, была ли ранее выделена память для другого ресурса. Однако если получение второго ресурса прошло неудачно, память первого ресурса все равно надо освободить. Использование вложенных конструкций if, с одной стороны, является естественным ответом на эту проблему, но с другой, затрудняет чтение и поддержку подобной функции. Кроме того, образуется несколько мест в коде, где происходит осовобождение ресурсов и обработка ошибок.

Одним из ответов на эту проблему может быть вынесение кода освобождения ресурсов и обработки ошибок в конец файла в отдельную секцию, а в основном коде выполнять переход к этой секции с помощью оператора **goto** при возникновении ошибки, наподобие следующего:

```c
void someFunction()
{
    if(!allocateResource1())    // выделяем память для 1-го ресурса
    {
        goto cleanup1;
    }
    if(!allocateResource2())    // выделяем память для 2-ого ресурса
    {
        goto cleanup2;
    }
    // основной код

// секция освобождения ресурсов и обработки ошибок
cleanup2:               
    cleanupResource2(); // освобождаем 2-й ресурс
cleanup1:
    cleanupResource1(); // освобождаем 1-й ресурс
}
```

Стоит отметить, что оператор **goto** часто не рекомендуется к применению в программированию вообще и в языке C в частности, так как употребление этого оператора может вести к уложнению кода и снижению читабельности программы. В связи с чем нередко различные стандарты приписывают не использовать данный оператор. Тем не менее конкретно в данном случае при должной организации мы можем уйти от чрезмерной вложенности ifов и отделить логически кода обработки ошибок и освобождения ресурсов от основной логики программы. А функция будет иметь одну точку выхода, что упрощает управление ее результатом. И конкретно данный паттерн довольно широко применяется в ядре Linux для обработки ошибки.

Рассмотрим пример. Пусть изначально у нас имеется следующая программа, которая ищет определенное слово в некотором файле:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// результат поиска
typedef enum {ERROR, FOUND, NOTFOUND} status;

status find(char*, char*, size_t);
status find_word(FILE*, char*, size_t, char*);

status find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    status result = ERROR;

    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

    // если удалось открыть файл
    if((file_pointer=fopen(file_name, "r"))){    

        // если удалось выделить память
        if((buffer=malloc(word_size))){

            result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова 
            free(buffer);
        }
        fclose(file_pointer);
    }
    return result;
}
// поиск слова
status find_word(FILE* file_pointer, char* word, size_t word_size, char* buffer){

    while(fgets(buffer, word_size, file_pointer)){

        if(strcmp(word, buffer)==0){ 

            return FOUND;   // если нашли слово
        }
    }
    return NOTFOUND;        // если не нашли слово
}
int main(void){
    char* filename ="test.txt";     // имя файла 
    char word[] = "hello";          // искомое слово
    size_t size = sizeof(word);     // размер слова

    status result = find(filename, word, size);

    switch(result) {
        case ERROR:
            printf("Error!\n");
            break;
        case NOTFOUND:
            printf("Text not found...\n");
            break;
        case FOUND:
            printf("Success! Text found!\n");
            break;

    }
}
```

Здесь функция `find()` получает извне имя файла для поиска, слово для поиска и размер слова. Чтобы найти слово, открываем файл и затем выделяем буфер в памяти для считывания данных. Затем вызывается функция `find_word()`, которая считывает символы из файла в буфер и проверяет на их соответствие искомому слову. В качестве результата возвращается одно из значений перечисления status, по которому мы можем узнать результат операции.

Причем функция `find()` сразу проверяет предусловия с помощью выражений `assert`, тем самым нивелируя пару конструкций if. А управление ресурсами и основные действия функции отделены путем вынесения поиска слова в отдельную функцию - find_word. Тем не менее применение вложенных if несколько снижает читабельность функции find

```c
if((file_pointer=fopen(file_name, "r"))){    
    if((buffer=malloc(word_size))){
    ....
    }
........
}
```

Причем подобным вложенных конструкций if может быть и больше. Теперь используем **goto**:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// результат поиска
typedef enum {ERROR, FOUND, NOTFOUND} status;

status find(char*, char*, size_t);
status find_word(FILE*, char*, size_t, char*);

status find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    status result = ERROR;

    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

   // если НЕ удалось открыть файл
    if(!(file_pointer=fopen(file_name, "r"))){    
        goto error_fileopen;
    }
    // если память НЕ выделена
    if(!(buffer=malloc(word_size))) {
        goto error_malloc;
    }

    result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова 

// секция освобождения ресурсов
    free(buffer);
error_malloc:
    fclose(file_pointer);
error_fileopen:
    return result;
}
// поиск слова
status find_word(FILE* file_pointer, char* word, size_t word_size, char* buffer){

    while(fgets(buffer, word_size, file_pointer)){

        if(strcmp(word, buffer)==0){ 

            return FOUND;   // если нашли слово
        }
    }
    return NOTFOUND;        // если не нашли слово
}

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);

    status result = find(filename, word, size);

    switch(result) {
        case ERROR:
            printf("Error!\n");
            break;
        case NOTFOUND:
            printf("Text not found...\n");
            break;
        case FOUND:
            printf("Success! Text found!\n");
            break;

    }
}
```

Теперь функция find проверяет выделение ресурсов и в случае ошибки переходит к определенной метке в секции в конце функции:

```c
if(!(file_pointer=fopen(file_name, "r"))){    
    goto error_fileopen;
}
// если память НЕ выделена
if(!(buffer=malloc(word_size))) {
    goto error_malloc;
}
```

В конце функции в отдельной секции происходит освобождение ресурсов и возвращение результата:

```c
// секция освобождения ресурсов
    free(buffer);
error_malloc:
    fclose(file_pointer);
error_fileopen:
    return result;
```

То есть, если файл успешно открыт, буфер выделен, поиск в файле произведен, то освобождается буфер, закрывается файл и возвращается результат.

Если при попытке выделить память для буфера произошла ошибка, то происходит переход к метке `error_malloc` и выполняется закрытие файла (так как память для буфера не выделена, соответственно ее освобождать не надо).

Если при открытии файла произошла ошибка, то выполняется переход к метке `error_fileopen`, и возвращается результат.

В прошлой теме рассматривалась проблема, когда функция использует множество ресурсов, выделяет и осовобождает для них память. Причем выделение одного ресурса зависит от успешности выделения другого. Если выделение первого ресурса прошло удачно, то выделяем второй ресурс. Но если получение второго ресурса прошло неудачно, память первого ресурса все равно надо освободить. И в этом случае для управления ресурсами обычно напрашивается применение вложенных конструкциий if. Но это может затруднять чтение и поддержку подобной функции, особенно когда ресурсов много. В прошлой теме в качестве возможного ответа на эту проблему применялся оператор `goto`, который при возникновении ошибки переходил к определенной метке в секции освобождения ресурсов. В качестве альтернативы можно использовать ленивое выделение ресурсов, когда каждый последующий ресурс выделяется, если успешно был выделен предыдущий ресурс, наподобие следующего:

```c
void someFunction()
{
    if((resource1=allocateResource1()) && (resource2=allocateResource2()))
    {
        // основной код
    }
    if(resource1) // если выделен resource1
    {
        freeResource1(); // очищаем его
    }
    if(resource2) // если выделен resource2
    {
        freeResource2(); // очищаем его
    }
}
```

И в данном случае, когда начинает выполняться первая конструкция **if**, то сначала выполняется выражение `resource1=allocateResource1()`, которое условно выделяет память для ресурса resource1. Если это выражение выполнилось успешно и возвратило ненулевое значение, выполняется второй операнд операции **&&** - выражение `resource2=allocateResource2()`, которое условно выделяет второй ресурс. И если второй ресурс также успешно выделен, то выполняются действия этой конструкции if.

После завершения первой конструкции if выполняется освобождение ресурсов, если они были успешно выделены. Таким образом, мы уходим от вложенности ifов. А освобождение ресурсов целенаправлено выполняется в одном месте - в конце функции. В то же время если надо выделить много ресурсов, то это перегружает условие в конструкции if, что опять же может усложнить ее понимание, отладку.

Применим этот паттерн на примере программы, которая ищет определенное слово в некотором файле:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// результат поиска
typedef enum {ERROR, FOUND, NOTFOUND} status;

status find(char*, char*, size_t);
status find_word(FILE*, char*, size_t, char*);

status find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    status result = ERROR;

    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

   // если удалось открыть файл и выделить память
    if((file_pointer=fopen(file_name, "r")) && (buffer=malloc(word_size))) 
    {
        result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова
    }

    // секция освобождения ресурсов
    if(buffer) free(buffer);
    if(file_pointer) fclose(file_pointer);

    return result;
}
// поиск слова
status find_word(FILE* file_pointer, char* word, size_t word_size, char* buffer){

    while(fgets(buffer, word_size, file_pointer)){

        if(strcmp(word, buffer)==0){ 

            return FOUND;   // если нашли слово
        }
    }
    return NOTFOUND;        // если не нашли слово
}

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);

    status result = find(filename, word, size);

    switch(result) {
        case ERROR:
            printf("Error!\n");
            break;
        case NOTFOUND:
            printf("Text not found...\n");
            break;
        case FOUND:
            printf("Success! Text found!\n");
            break;

    }
}
```

Здесь функция `find()` получает извне имя файла для поиска, слово для поиска и размер слова. Чтобы найти слово, открываем файл и затем выделяем буфер в памяти для считывания данных. И только если эти операции выполнились успешно, то с помощью функции `find_word()` считываем символы из файла в буфер и проверяем на их соответствие искомому слову:

```c
if((file_pointer=fopen(file_name, "r")) && (buffer=malloc(word_size))) 
{
    result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова
}
```

В конце функции `find()` проверяем выделенные ресурсы и очищаем их

```c
// секция освобождения ресурсов
if(buffer) free(buffer);
if(file_pointer) fclose(file_pointer);
```

Если функция использует множество ресурсов, выделяет и осовобождает для них память, а выделение одного ресурса зависит от успешности выделения другого, то на уровне кода программы это может вылить в каскад вложенных конструкциий **if**. Что, в свою очередь, может затруднять чтение и поддержку подобной функции, особенно когда ресурсов много. В прошлых темах в качестве возможного решения предалагалось применение оператора `goto` или ленивое выделение ресурсов. Тем не менее при подобных подходах по мере возрастания количество используемых ресурсов все равно повышается сложность функции, снижается ее читабельность. И в качестве еще одного решения можно применять концепцию конструкторов и деструкторов.



Вообще конструкторы и деструкторы относятся больше к парадигме объектно-ориентированного программирования, к которой язык Си не принадлежит. Например, в С++ на уровне классов определяются специальные функции - конструкторы, которые срабатывают при создании объекта и призваны выделять память, различные используемые ресурсы. И также объект имеет специальную функцию деструктора, которая выполняется при удалении объекта и призвана особождать используемые ресурсы. На уровне программы на языке Си мы можем определить подобные функции, которые будут совсместно выделять и освобождать ресурсы. Вначале функции выполняется конструктор, а в конце функции выполняется деструктор, наподобие следующего:



```c

void someFunction()
{
    allocateResources();    // условный конструктор
    // некоторые основные действия
    freeResources();        // условный деструктор
}
```



Если ресурсы не представляют глобальные переменные, а определяются локально в функции, то они передаются в конструктор/деструктор через параметры. Чтобы не передавать все множество ресурсов по отдельности, можно определить один сборный объект. Если выделение какого-то ресурса прошло неудачно, то эта информация сохраняется в переменную (например, в виде значения NULL). А при использовании или очистке ресурсов эта переменная проверяется на валидность.




Рассмотрим пример. Пусть изначально у нас имеется следующая программа, которая ищет определенное слово в некотором файле:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// результат поиска
typedef enum {ERROR, FOUND, NOTFOUND} status;

status find(char*, char*, size_t);
status find_word(FILE*, char*, size_t, char*);

status find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    status result = ERROR;

    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

    // если удалось открыть файл
    if((file_pointer=fopen(file_name, "r"))){    
        
        // если удалось выделить память
        if((buffer=malloc(word_size))){
        
            result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова 
            free(buffer);
        }
        fclose(file_pointer);
    }
