```



Здесь нас интересует прежде всего функция `find()`, которая получает извне имя файла для поиска, слово для поиска и размер слова. Чтобы найти слово, открываем файл и затем выделяем буфер в памяти для считывания данных. Затем вызывается функция `find_word()`, которая считывает символы из файла в буфер и проверяет на их соответствие искомому слову. В качестве результата возвращается одно из значений перечисления status, по которому мы можем узнать результат операции.



Причем функция `find()` сразу проверяет предусловия с помощью выражений `assert`, тем самым нивелируя две конструкции if. А управление ресурсами и основные действия функции отделены путем вынесения поиска слова в отдельную функцию - find_word. Тем не менее применение вложенных if несколько снижает читабельность функции find



```c

if((file_pointer=fopen(file_name, "r"))){    
    if((buffer=malloc(word_size))){
    ....
    }
........
}
```



Причем подобным вложенных конструкций if может быть и больше по мере увеличения используемых ресурсов.



Другой недостаток - если мы рассматриваем выделение ресурсов и их освобождение как две разные обязанности, то функция find не соответствует принципу единой ответственности. Теперь изменим программу, определив и применив функции конструктора и деструктора:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// результат поиска
typedef enum {ERROR, FOUND, NOTFOUND} status;

typedef struct
{
    FILE* file_pointer;
    char* buffer;
    char* word;
    size_t word_size;
} Resources;

status find(char*, char*, size_t);
status find_word(Resources*);
Resources* constructor(char*, char*, size_t);
void destructor(Resources*);

Resources* constructor(char* file_name, char* word, size_t word_size)
{
    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

    Resources* resources = malloc(sizeof(Resources));
    if(resources)
    {
        // открываем файл
        resources->file_pointer=fopen(file_name, "r");
        // выделяем память для буфера
        resources->buffer = malloc(word_size);
        // если при выделении какого-то ресурса произошла ошибка
        if(!resources->file_pointer || !resources->buffer)
        {
            destructor(resources);  // вызываем деструктор, который освобождает остальные ресурсы
            return NULL;
        }
        resources->word = word;
        resources->word_size = word_size;
    }
    return resources;
}

// деструктор - освобождаем ресурсы
void destructor(Resources* res)
{
    if(res)   // если ресурсы ранее были выделены
    {
        if(res->buffer)   // если буфер выделен
        {
            free(res->buffer); // освобождаем память буфера
        }
        if(res->file_pointer) // если файл был открыт
        {
            fclose(res->file_pointer);    // закрываем файл
        }
        free(res);
    }
}

status find(char* file_name, char* word, size_t word_size)
{
    status result;
    Resources* res = constructor(file_name, word, word_size);
    result = find_word(res);
    destructor(res);

    return result;
}
// поиск слова
status find_word(Resources* res)
{
    if(res == NULL)   // если выделение ресурсов прошло неудачно
    {
        return ERROR;       // возвращаем код ошибки
    }
    while(fgets(res->buffer, res->word_size, res->file_pointer)){
        
        if(strcmp(res->word, res->buffer)==0){ 

            return FOUND;   // если нашли слово
        }
    }
    return NOTFOUND;        // если не нашли слово
}

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);

    status result = find(filename, word, size);

    switch(result) {
        case ERROR:
            printf("Error!\n");
            break;
        case NOTFOUND:
            printf("Text not found...\n");
            break;
        case FOUND:
            printf("Success! Text found!\n");
            break;
    }
}
```



Разберем основные моменты. Прежде всего для управления ресурсами определяется структура Resources:



```c

typedef struct
{
    FILE* file_pointer;
    char* buffer;
    char* word;
    size_t word_size;
} Resources;
```



Она хранит указатель на файл, указатель на выделенный (или не веделенный) буфер, указатель на искомое слово и размер слова.



Объект данной структуры создается в функции конструктора:



```c

Resources* constructor(char* file_name, char* word, size_t word_size)
{
    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

    Resources* resources = malloc(sizeof(Resources));
    if(resources)
    {
        // открываем файл
        resources->file_pointer=fopen(file_name, "r");
        // выделяем память для буфера
        resources->buffer = malloc(word_size);
        // если при выделении какого-то ресурса произошла ошибка
        if(!resources->file_pointer || !resources->buffer)
        {
            destructor(resources);  // вызываем деструктор, который освобождает остальные ресурсы
            return NULL;
        }
        resources->word = word;
        resources->word_size = word_size;
    }
    return resources;
}
```



Функция конструктора в качестве параметров принимает все те значения, которые ранее передавались в функцию find и опять же с помощью выражений `assert` вначале проверяет предусловия, несоблюдение которых приведет к завершению программы. Затем выделяется память под структуру Resources:



```c

Resources* resources = malloc(sizeof(Resources));
```



Если выделение памяти прошло успешно, то открываем файл и выделяем память для буфера:



```c

if(resources)
{
    // открываем файл
    resources->file_pointer=fopen(file_name, "r");
    // выделяем память для буфера
    resources->buffer = malloc(word_size);
```



Но если либо открытие файла, либо выделение памяти прошло неудачно, то очищаем ресурсы (которые были выделены) с помощью деструктора и возвращаем NULL:



```c

if(!resources->file_pointer || !resources->buffer)
{
    destructor(resources);  // вызываем деструктор, который освобождает остальные ресурсы
    return NULL;
}
```



Это гарантирует, что если, например, память для буфера была выделена, но файл не был открыт, то файл для буфера будет освобождена. Если все прошло удачно, возвращаем созданную структуру.



Функция деструктора освобождает ранее выделенные ресурсы.



```c

void destructor(Resources* res)
{
    if(res)   // если ресурсы ранее были выделены
    {
        if(res->buffer)   // если буфер выделен
        {
            free(res->buffer); // освобождаем память буфера
        }
        if(res->file_pointer) // если файл был открыт
        {
            fclose(res->file_pointer);    // закрываем файл
        }
        free(res);
    }
}
```



Тут все просто - освобождаем выделенные ресурсы с помощью соответствующих функций. Стоит только отметить, что в конструкторе выделение ресурсов идет только после создания структуры Resources. Соответственно в деструкторе проверяем выделение памяти для этой структуры и только после этого освобождаем ресурсы.



В функции `find()` сначала вызываем конструктор, получаем из него ресурсы в виде структуры Resources и передаем их в функцию find_word для поиска слова. И после этого вызываем деструктор:



```c

status result;
Resources* res = constructor(file_name, word, word_size);
result = find_word(res);
destructor(res);
```



В самой функции find_word сначала проверяем структуру Resources на NULL, так как если она равна NULL, то значит выделение ресурсов прошло неудачно, и нет смысла искать слово:



```c

status find_word(Resources* res)
{
    if(res == NULL)   // если выделение ресурсов прошло неудачно
    {
        return ERROR;       // возвращаем код ошибки
    }
```



Использование функций-конструкторов и функций-деструкторов, с одной стороны, может увеличить общее количество кода. Но с другой стороны, мы достигаем четкого разделения между выделением и освобождением ресурсов, можем управлять этими процессами по отдельности, а также удаляем каскад вложенных конструкций if.

Если программа имеет сложную структуру, где выделение динамической памяти производится в одном месте, ее использование в другом, а освобождение памяти в третем месте программы, то возрастает риск использования недействительных указателей и соответственно программных ошибок. Например, можно столкнуться с использованием неинициализированного указателя или указателя, память по которому уже была освобождена или повторно освободить память.

Стандартное решение в даннном случае состоит в том, чтобы проверять валидность указателя (проверка на NULL) перед использованием. При определении указателя после освобождения памяти ему присваивается значение 0 или **NULL**:

```c
void someFunction()
{
    char* pointer = NULL; // явным обарзом инициализируем указатель нулем
    pointer = malloc(1024); // выделяем память

    if (pointer)    // проверяем указатель на NULL
    {
        // некоторая работа с памятью по указателю
    }

    free(pointer);  // освобождаем память по указателю
    pointer = NULL; // сбрасываем указатель в ноль
}
```

Проверка указателя и присвоения ему нуля увеличивает код, однако упрощает идентификацию тех мест в программе, где с указателем может возникнуть ошибка. Также повторное освобождение памяти по указателю, которому ранее присвоили NULL, не окажет никакого влияния на программу:

```c
free(pointer);  // освобождаем память по указателю
pointer = NULL; // сбрасываем указатель в ноль
free(pointer);  // ни на что не влияет
```

Рассмотрим следующую программу:

```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// получаем длину файла
int getFileLength(FILE* fp)
{
    fseek(fp, 0, SEEK_END);
    int file_length = ftell(fp);
    return file_length;
}
// считываем файл в buffer
void readFile(FILE* fp, char* buffer, int file_length)
{
    fseek(fp, 0, SEEK_SET);
    int read_elements = fread(buffer, 1, file_length, fp);
    buffer[read_elements] = '\0';   // устанавливем концевой нулевой байт для строки
}
// вывод файла на консоль
void printFile(char* filename)
{
    FILE* fp = 0; // инициализируем нулем
    char* text = 0;         // инициализируем нулем 

    assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу

    fp = fopen(filename, "r");  // открываем файл
    assert(fp && "Unable to open file!\n"); // если не удалось открыть файл, прерываем программу

    int file_length = getFileLength(fp);  // получаем длину файла
    if(file_length > 0)
    {
        text = malloc(file_length);
        if(text)    // если удалось выделять память
        {
            readFile(fp, text, file_length);  // считываем файл
            printf("%s\n",text);

            free(text); // освобождаем память
            text = 0;   // сбрасываем значение указателя в ноль
        }
    }
    fclose(fp);     // закрываем файл
    fp = 0;         // сбрасываем значение указателя в ноль
}

int main(void)
{
    char* filename = "test.txt";
    printFile(filename);
}
```

Данная программа предназначена для вывода на консоль текста из файла. Для этого определена функция printFile(), которая принимает имя файла. Вначале она определяет используемые указатели для взаимодействия с файлом указатель **FILE*** и указатель на буфер для считывания файла buffer:

```c
FILE* fp = 0; // инициализируем нулем
char* text = 0;         // инициализируем нулем
```

Оба указателя инициализированы нулем. Это далее поможет при проверке иденфицировать, что файл открыт, а буфер успешно выделен.

Затем с помощью выражения **assert()** проверяется корректность имени файла - проверка предусловия:

```c
assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу
```

Далее открываем файл и проверяем что файл открыт:

```c
fp = fopen(filename, "r");  // открываем файл
assert(fp && "Unable to open file!\n"); // если не удалось открыть файл, прерываем программу
```

Выражение `assert()` проверяет, что fp не равен NULL, иначе прерывает программу. В общем случае у нас есть два способа обработки корректности указателя: жесткий с прерыванеим программы и мягкий с некоторой обработкой и продолжением работы программы. Оба способа имеют свои плюсы и минусы. В данном случае прерываем программу, так как дальше нет смысла в работе функции и вообще программы, так как файл не удалось открыть. Но это не аксиома, можно использовать более мягкие способы, например, проверку в конструкции if, особенно если дальше идут некоторые выражения, которые должны выполняться и при неудачне при открытии файла.

Далее с помощью вспомогательной функции getFileLength получаем длину файла:

```c
int file_length = getFileLength(fp);  // получаем длину файла
```

Если длина файла меньше 1 байта, то нет смысла считывать его содержимое. Поэтому проверяем полученную длину и выделяем буфер для считывания данных:

```c
if(file_length > 0)
{
    text = malloc(file_length);
    if(text)    // если удалось выделять память
    {
        readFile(fp, text, file_length);  // считываем файл
        printf("%s\n",text);

        free(text); // освобождаем память
        text = 0;   // сбрасывем значение указателя
    }
}
```

Если удалось выделить память, то считываем данные с помощью функции readFile и выводим считанный текст на строку. В отличие от проверки указателя на файл fp здесь используется мягкий подход с проверкой в конструкции if. После завершения работы с буфером его память освобождается, а указатель сбрасывается в 0, что позволит избежать висячих указателей:

```c
free(text); // освобождаем память
text = 0;   // сбрасывем значение указателя
```

В конце закрываем файл и сбрасываем указатель файла в 0:

```c
fclose(fp);     // закрываем файл
fp = 0;         // сбрасываем значение указателя в ноль
```

В данном случае ситуация в некотором смысле искусственная, поскольку после особождения памяти указатель на нее никак не использует, и также указатель на файл также никак не используется после закрытия файла. Поэтому здесь нет большого смысла в сбросе указателей в ноль после освобождения ресурсов. Однако немного изменим функцию printFile:

```c
void printFile(char* filename)
{
    FILE* fp = 0; // инициализируем нулем
    char* text = 0;         // инициализируем нулем 

    assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу

    fp = fopen(filename, "r");  // открываем файл
    assert(fp && "Unable to open file!\n"); // если не удалось открыть файл, прерываем программу

    int file_length = getFileLength(fp);  // получаем длину файла
    if(file_length > 0)
    {
        text = malloc(file_length);
        if(text)    // если удалось выделять память
        {
            readFile(fp, text, file_length);  // считываем файл
            printf("%s\n",text);
            free(text); // освобождаем память
            // text = 0  // закомментируем сброс буфера в ноль
        }
    }

    // пробуем вывести текст после освобождения памяти
    if(text)    // если удалось выделять память
    {
        printf("%s\n",text);
        free(text); // освобождаем память
    }

    fclose(fp);     // закрываем файл
    fp = 0;         // инициализируем указатель на файл нулем
}
```

Здесь после освобождения памяти по указателю text повторно проверяем валидность указателя и пробуем вывести текст на консоль. Результат в этом случае будет неопределенным. Вполне возможно, что будет выведен ранее считанный из файла текст. Однако формально память уже освобождено, и мы получили висячий указатель (dangling pointer), использование которого в дальнейшем может служить источником программных ошибок. Соответственно сброс указателя в ноль сразу после освобождения с последующей проверкой указателя на валидность позволил бы избавиться от ряда проблем.

То же самое касается и других ресурсов, например, указателя на файл - даже если мы закроем файл, указатель сохранит свое значение. И нам ничего не помешает попытаться выполнить с файлом по этому указателю какие-нибудь операции. Сброс же указателя в ноль с последующей проверкой на NULL позволит избежать ненужных операций с закрытым файлом.

При многократном выделении динамической памяти в разных местах программы, возможно, возникнет необходимость сразу же на месте обработать ошибки при выделении памяти. Однако таких мест в программе может быть много, и определять проверку в каждом месте может быть трудозатратным и ведет к увеличению кода, усложныет его. Кроме того, в дальнейшем может возникнуть проблема, что надо изменить механизм обработки ошибок, для чего придется обновить все эти места. И в данном случае решением может быть создание обертки над выделением памяти, где будет выполняться обработка ошибок выделения памяти или еще какие-нибудь сопутствующие операции, например, логгирование. Данный паттерн еще называют **Allocation Wrapper**

Например, можно определить функцию, которая проверяет выделение памяти:

```c
// обертка над выделением памяти
void* allocationWrapper(size_t size)
{
    void* pointer = malloc(size);
    assert(pointer && "Unable to allocate a memory");
    return pointer;
}

void someFunction()
{
    char* buffer = allocationWrapper(1024);
    // некоторая работа с buffer
    free(buffer);
}
```

То есть определяется функция-обертка, в которой выделяется память. При неудачном выделении функция **malloc** возвращает **NULL**, и функция-обертка обрабатывает этот результат и затем возвращает его. В примере выше функция-обертка для проверки применяет выражение **assert()**, соответственно, если выделение памяти прошло неудачно, и pointer равен NULL, то выполнение программы прерывается. Это жесткий вариант реакции на ошибку выделения памяти. Он удобен тем, что не надо писать много кода, сложную по структуре логику. В тоже время этот вариант не всегда может подойти. И в этом случае можно препочесть более мягкий вариант обработки - во внешнем коде проверять результат функции-обертки.

Например, возьмем следующую программу:

```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// функция выделения памяти с проверкой
void* create(size_t size)
{
    void* buffer = malloc(size);
    if(!buffer) printf("Unable to allocate memory\n");
    return buffer;
}

// обертка на освобождением памяти
void delete(void *buffer)
{
    free(buffer);
    buffer = 0;
}
// получаем длину файла
int getFileLength(FILE* fp)
{
    fseek(fp, 0, SEEK_END);
    int file_length = ftell(fp);
    return file_length;
}
// считываем файл в buffer
void readFile(FILE* fp, char* buffer, int file_length)
{
    fseek(fp, 0, SEEK_SET);
    int read_elements = fread(buffer, 1, file_length, fp);
    buffer[read_elements] = '\0';   // устанавливем концевой нулевой байт для строки
}
void printFile(char* filename)
{
    FILE* fp = 0; // инициализируем нулем
    char* text = 0;         // инициализируем нулем 

    assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу
    fp = fopen(filename, "r");  // открываем файл
    assert(fp && "Unable to open file!\n"); // если не удалось открыть файл, прерываем программу

    int file_length = getFileLength(fp);  // получаем длину файла
    if(file_length > 0)
    {
        text = create(file_length); // выделяем память
        if(text)    // если удалось выделять память
        {
            readFile(fp, text, file_length);  // считываем файл
            printf("%s\n",text);
            delete(text); // освобождаем память
        }
    }

    fclose(fp);     // закрываем файл
    fp = 0;         // инициализируем указатель на файл нулем
}

int main(void)
{
    char* filename = "test.txt";
    printFile(filename);    // выводим текст из файла filename
}
```

Здесь функция `create()` выступает в роли функции-обертки над `malloc()` и принимает размер выделяемой памяти:

```c
void* create(size_t size)
{
    void* buffer = malloc(size);
    if(!buffer) printf("Unable to allocate memory\n");
    return buffer;
}
```

В данном случае если выделение памяти прошло неудачно, логгируем на консоль сообщение об ошибке. И в любом случае возвращает указатель.

Функция `delete()` также является функцией-оберткой, только над функцией `free()`

```c
void delete(void *buffer)
{
    free(buffer);
    buffer = 0;
}
```

Здесь освобождаем память и сбрасываем указатель в ноль, чтобы при последуюших проверках он считался недействительным.

Основная часть программы разворачивается в функции printFile, которая считывает текст из файла и выводит на консоль. Для этого она сначала открывает файл, затем использует определенную ранее функцию getFileLength для получения размера файла в байтах.

```c
FILE* fp = 0; // инициализируем нулем
char* text = 0;         // инициализируем нулем 

assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу

fp = fopen(filename, "r");  // открываем файл
assert(fp && "Unable to open file!\n"); // если не удалось открыть файл, прерываем программу

int file_length = getFileLength(fp);  // получаем длину файла
```

Полученную длину файла передаем в функцию-обертку над malloc - функцию create для выделения памяти нужного размера:

```c
if(file_length > 0)
{
    text = create(file_length); // выделяем память
```

Если выделение памяти прошло успешно, и функция create возвратила ненулевой указатель, то считываем в выделенный буфер данные из файла с помощью дополнительной функции readFile и выводим содержимое буфера на консоль:

```c
if(text)    // если удалось выделять память
{
    readFile(fp, text, file_length);  // считываем файл
    printf("%s\n",text);
    delete(text); // освобождаем память
}
```

Причем в конце для освобождения памяти выполняем другую функцию-обертку - delete.

Таким образом, мы определяем единую точку для обработки выделения и освобождения памяти в виде функций create и delete.

В примере выше продемонтрирован мягкий вариант обработки ошибки при выделении памяти - внешний код вызывает функцию-обертку create, получает из нее указатель и решает, что делать дальше. В каких-то условиях этот может быть единственный возможный способ реакции на неудачу при выделении памяти. Тем не менее он ведет к усложнению структуры программы. Так, получив из функции create указатель, мы вынуждены дополнительно проверять его на NULL. Но в ситуациях, где не требуется продолжать работу программу в случае ошибки, более предпочтительным может быть жесткий подход - прерывание программы при неудаче при выделении памяти. Например:

```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// функция выделения памяти с проверкой
void* create(size_t size)
{
    void* buffer = malloc(size);
    // проверяем выделение памяти и при неудаче прерываем программу
    assert(buffer && "Unable to allocate memory");    
    return buffer;
}

// обертка на освобождением памяти
void delete(void *buffer)
{
    free(buffer);
    buffer = 0;
}
// получаем длину файла
int getFileLength(char* filename)
{
    FILE* fp = fopen(filename, "r");  // открываем файл
    assert(fp && "Unable to open file"); // если не удалось открыть файл, прерываем программу
    fseek(fp, 0, SEEK_END);
    int file_length = ftell(fp);
    fclose(fp);
    return file_length;
}
// считываем файл в buffer
void readFile(char* filename, char* buffer, int file_length)
{
    FILE* fp = fopen(filename, "r");  // открываем файл
    assert(fp && "Unable to open file"); // если не удалось открыть файл, прерываем программу
    int read_elements = fread(buffer, 1, file_length, fp);
    buffer[read_elements] = '\0';   // устанавливем концевой нулевой байт для строки
    fclose(fp);
}
void printFile(char* filename)
{
    char* text = 0;         // инициализируем нулем 
    assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу 

    int file_length = getFileLength(filename);  // получаем длину файла
    if(file_length > 0)
    {
        text = create(file_length); // выделяем память
        // проверка на NULL уже не нужна, если выделение памяти прошло неудачно, то программа прерывается
        readFile(filename, text, file_length);  // считываем файл
        printf("%s\n",text);
        delete(text); // освобождаем память
    }
}

int main(void)
{
    char* filename = "test.txt";
    printFile(filename);
}
```

Теперь в функции create проверяем выделение памяти с помощью выражения `assert()`:

```c
void* create(size_t size)
{
    void* buffer = malloc(size);
    // проверяем выделение памяти и при неудаче прерываем программу
    assert(buffer && "Unable to allocate memory");    
    return buffer;
}
```

Если не удалось выделить память, прерываем программу, так как по большому счету дальше продолжать программу нет смысла.

Открытие файла перенесено непосредственно в функции getFileLength (получение длины) и readFile (считывание файла). А в основной функции printFile уходим от использования одной конструкции if с дополнительной проверкой указателя, тем самым упрощая структуру программы:

```c
int file_length = getFileLength(filename);  // получаем длину файла
if(file_length > 0)
{
    text = create(file_length); // выделяем память
    // проверка на NULL уже не нужна, если выделение памяти прошло неудачно, то программа прерывается
    readFile(filename, text, file_length);  // считываем файл
    printf("%s\n",text);
    delete(text); // освобождаем память
}
```

Освобождение памяти, даже будучи выполненым, может быть чревато ошибками. Например, если освободить память раньше, чем нужно, то можно получить "висячий указатель" (dangling pointer). Либо можно по ошибки освободить одну и ту же память дважды, что приведет к неопределенному поведению. Поэтому если программа использует динамическую память для хранения данных, но при этом память выделяется не часто, а сама программа выполняется довольно быстро, то можно переложить на операционную систему обязанность по особождению памяти. И после завершения программы ОС сама освободит всю связанную с программой память.

Стоит отметить, что данное обстоятельно не стоит использовать в качестве оправдания вообще не освобождать память, поскольку диапазон возможных ситуаций, где подобное можно применять, довольно ограничен. Так, если программа часто выделяет память или работает продолжительное время, очевидно, что данный подход не подойдет. Кроме того, программа может эволюционировать, соответственно ситуация может меняться, а подобный подход может быть уже не применим.

Например, возьмем следующую программу:

```c
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

// получаем длину файла
int getFileLength(FILE* fp)
{
    fseek(fp, 0, SEEK_END);
    int file_length = ftell(fp);
    return file_length;
}
// считываем файл в buffer
void readFile(FILE* fp, char* buffer, int file_length)
{
    fseek(fp, 0, SEEK_SET);
    int read_elements = fread(buffer, 1, file_length, fp);
    buffer[read_elements] = '\0';   // устанавливаем концевой нулевой байт для строки
}

int main(void)
{
    char* filename = "test.txt"; 
    FILE* fp = fopen(filename, "r");
    // если не удалось открыть файл, останавливаем программу
    assert(fp && "Unable to open file!\n");

    int file_length = getFileLength(fp);  // получаем длину файла
    char* text = malloc(file_length);
    if(text)    // если удалось выделять память
    {
        readFile(fp, text, file_length);  // считываем файл
        printf(text);
    }
    fclose(fp);
}
```

Здесь функция getFileLength получает длину файла, а функция readFile считывает файл в строку. В функции main сначала считывем размер файла и затем используем этот размер для выделения буфера. Если выделение памяти прошло успешно, то считываем в буфер текстовый файл (в данном случае файл test.txt, который, как подразумевается, находится в папке программы).

После считывания файла и вывода считанного текста на консоль буфер явным образом не закрывается. По большому счету в этом нет большого смысла, поскольку после вывода строки фактически идет закрытие файла и конец программы. Соответственно после этого операционная система сама очистит память приложения.

Нередко программе в течении работы довольно часто приходится выделять и освобождать память, и точно количество выделяемой памяти на момент компиляции неизвестно, оно становится известным в некоторый момент выполнения программы. Однако также нередко приходится выделять память одного и того же размера. Либо, хотя на момент компиляции мы не значем точный размер выделяемой памяти, но мы можем знать максимальный размер, и мы можем быть уверены, что больше этого размера выделять память не придется.

Частое выделение-освобождение памяти несет дополнительные издержки, снижающие производительность. Кроме того, существует проблема дефрагментации. И если размер наибольшего свободного фрагмента меньше размера запрошенной памяти, то выделение памяти завершится неудачей, даже если совокупный размер всех свободных фрагментов больше размера запрошенной памяти. Потому что функция **malloc()** выделяет последовательный набор байтов. И в этом случае решением может быть применение **пула памяти** или паттерна **Memory Pool**

Пул памяти может:

- располагаться в статической памяти

- выделяться в динамической памяти, а при завершении работы программы освобождаться с помощью функции free()

Оба места хранения имеют свои достоинства и недостатки. Например, выделение пула в динамической памяти позволит при необходимости подгружать в процессе работы программы дополнительную память, если потребуется увеличение пула. Но в этом случае мы сталкиваемся с необходимость следить за должным освобождением памяти, плюс несем дополнительные издержки, связанные с выделением-освобождением памяти.

Обращение к статической памяти происходит быстрее, однако она выделяется на этапе запуска программы, что может немного замедлить старт приложения. Кроме того, в этом случае сложнее организовать увед=личение пула в случае необходимости.

В простейшем и общем случае реализацию пула памяти можно представить следующим образом:

```c
#define MAX_ELEMENTS 10    // максимальное количество элементов
#define ELEMENT_SIZE 255   // размер одного элемента

// структура, которая представляет один блок в пуле памяти
typedef struct
{
  bool occupied;
  char memory[ELEMENT_SIZE];
}PoolBlock;

static PoolBlock memory_pool[MAX_ELEMENTS]; // сам пул памяти

// если переданный размер не превышает максимальный, то возвращает указатель на свободный блок памяти 
// если свободных блоков нет или размер больше максимального, то возврашает NULL
void* take(size_t size)
{
  if(size <= ELEMENT_SIZE)   // если не больше размера одного блока
  {
    for(int i=0; i<MAX_ELEMENTS; i++)   // проходим по всем блокам
    {
      if(memory_pool[i].occupied == 0)    // если блок не занят
      {
        memory_pool[i].occupied = 1;      // указываем, что он занят
        return &(memory_pool[i].memory);    // возвращаем адрес на память этого блока
      }
    }
  }
  return NULL;
}

// освобождает указатель на блок памяти
void release(void* pointer)
{
  for(int i=0; i<MAX_ELEMENTS; i++)  // проходим по всем блокам
  {
    if(&(memory_pool[i].memory) == pointer) // если указатель указывает на память определенного блока
    {
      memory_pool[i].occupied = 0;    // указываем, что блок теперь свободен
      return;
    }
  }
}
```

В этом листинге пул расположен в статической памяти. Пул делится на блоки. Каждый блок представлен структурой PoolBlock. Каждый блок определяет поле occupied, которое указывает, свободен ли блок. Также в блоке определен массив байтов memory - собственно память блока. Размер памяти блока задается значением ELEMENT_SIZE. А общее количество блоков в пуле задается значением MAX_ELEMENTS.

Для управления пулом определены две функции. Функция take получает размер памяти, которую надо выделить. Если этот размер меньше или равен размеру одного блока, то проходим по всем блокам и смотрим, какой из них свободен. Если нашли свободный, то возвращаем указатель на массив memory блока памяти. В остальных случаях возвращаем NULL.

Функция release освобождает блок памяти. Она принимает указатель на блок памяти, находит этот блок и сбрасывает его поле occupied в 0, что указывает, что блок свободен.

Но это простейшая реализация. В зависимости от конкретной ситуации и задач, естественно она может меняться. Например, для работы в многопоточных системах может потребоваться добавления некоторых механизмов для разграничения доступа, потому что статическая память едина для всех потоков программы. Тем не менеев данной реализации следует отметить, что мы знаем макисмальный размер запрашиваемой памяти (размер одного блока - ELEMENT_SIZE), хотя мы можем естественно хранит в блоке данные и меньшего размера. И также мы предполагаем, какое максимальное количество подобных блоков единовременно могут быть задействовано в программе (значение MAX_ELEMENTS).

Таким образом, с помощью пула мы можем частично уйти от проблемы фрагментации, особенно при применении статической памяти для хранении пула. Кроме того, доступ к памяти будет происходить быстрее. Тем нее менее проблема может возникнуть, если нам вдруг потребуется блок большей длины, либо количество доступных блоков будет исчерпано. Другая проблема - мы можем использовать только часть блоков, тогда остальные блоки будут впустую расходовать память. Третья пробоема - увеличение времени запуска приложения, которое тратится на инициализацию пула.

Простейший пример использования пула:

```c
#include <stdio.h>

#define MAX_ELEMENTS 20    // максимальное количество элементов
#define ELEMENT_SIZE 255   // размер одного элемента

// структура, которая представляет один блок в пуле памяти
typedef struct
{
  int occupied;
  char memory[ELEMENT_SIZE];
} PoolBlock;

static PoolBlock memory_pool[MAX_ELEMENTS]; // сам пул памяти

// если переданный размер не превышает максимальный, то возвращает указатель на свободный блок памяти 
// если свободных блоков нет или размер больше максимального, то возврашает NULL
void* take(size_t size)
{
  if(size <= ELEMENT_SIZE)   // если не больше размера одного блока
  {
    for(size_t i=0; i<MAX_ELEMENTS; i++)   // проходим по всем блокам
    {
      if(memory_pool[i].occupied == 0)    // если блок не занят
      {
        memory_pool[i].occupied = 1;      // указываем, что он занят
        return &(memory_pool[i].memory);    // возвращаем адрес на память этого блока
      }
    }
  }
  return NULL;
}

// освобождает указатель на блок памяти
void release(void* pointer)
{
  for(int i=0; i<MAX_ELEMENTS; i++)  // проходим по всем блокам
  {
    if(&(memory_pool[i].memory) == pointer) // если указатель указывает на память определенного блока
    {
      memory_pool[i].occupied = 0;    // указываем, что блок теперь свободен
      return;
    }
  }
}

int main(void)
{
    int bufSize = 16;
    char* buffer = take(bufSize);  // запрашиваем память размером 16 байт
    if(buffer) // если память выделена
    {
        printf("Enter name: ");
        fgets(buffer, bufSize, stdin);  // вводим в buffer строку с консоли размером bufSize

        printf("Your name: %s\n", buffer);
        release(buffer);    // освобождаем память
    }
    else
    {
        printf("Unable to allocate memory\n");
    }
}
```

В данном случае запрашиваем в пуле памяти блок размеров в 16 байт и затем вводим в этот блок строку с консоли.

Причем хотя память одного блока представляет массив char, но в реальности мы можем разместить там данные любого типа или набора типов, размер которого укладывается в размер блока. Например, поместим в пул значение типа **unsigned**:

```c
int main(void)
{
    unsigned* age = take(sizeof(unsigned));
    if(age)
    {
        printf("Enter age: ");
        scanf("%u", age);  // вводим в age число unsigned

        printf("Your age: %u\n", *age);
        release(age);    // освобождаем память
    }
    else
    {
        printf("Unable to allocate memory\n");
    }
}
```

Здесь для краткости приведен только код функции main, так как остальной код остается тем же. И в данном случае выделяем память под одно значение типа `unsigned`, на которое указывает переменная-указатель age.

Если в процессе выполнения функции может произойти некоторая ошибка, то вполне возможно мы захотим возвратить информацию об ошибке вызывающей стороне, чтобы вызывающий код мог узнать, что произошла ошибка, и как-то отреагировать на нее. В качестве решения можно было бы возратить из функции статусный код ошибки. Однако вполне возможно функция уже возвращает некоторый результат. В самом простом случае решение состоит в том, чтобы для статуса ошибки использовать одно из значений возвращаемого типа.

Например, встроенная функция **getchar()** считывает один символ и возвращает его в виде значения типа `int`. Если же при считывании произошла ошибка, функция возвращает значение `EOF`, в качестве которого обычно используется число -1. Это число укладывается в значения типа int и в то же время не пересекается с возвращаемыми числовыми кодами символов.

Рассмотрим простейший пример:

```c
#include <stdio.h>
#include <string.h>
#include <assert.h>

#define USERS_NUMBER 5      // количество объектов в массиве

// структура условной базы данных
typedef struct
{
    char* users[USERS_NUMBER];
} database;


int find(database* db, char*);

int main(void){

    // база данных
    database db = {.users = {"Tom", "Sam", "Bob", "Alice", "Kate"}};

    // имя для поиска в базе данных
    char* user = "Alice";
    int index = find(&db, user);
    if(index > -1)
    {
        printf("User index: %d\n", index);
    }
    else
    {
        printf("User not found\n");
    }
}      

// условная функция поиска в базе данных
int find(database* db, char* user)
{
    assert(db!=NULL && "Database is invalid");
    assert(user!=NULL && "User is undefined");

    for(size_t i =0; i < USERS_NUMBER; i++)
    {
        // если нашли имя, возвращаем индекс в массиве
        if(strcmp(db->users[i], user)==0)
        {
            return i;
        }
    }
    return -1;  // если не нашли, возвращаем -1
}
```

Здесь определена структура database, которая представляет условную базу данных и хранит данные в массиве строк users. Допустим, это будут имена пользователей.

Для поиска в этой базе данных определенного пользователя определена функция find. Она принимает объект базы данных и искомое имя. Функция find проходит по строкам в массиве users и с помощью функции strcmp сравнивает имя user с каждым элементом в массиве users. Если переданный пользователь есть в массиве, то возвращается его индекс. Если указанный пользователь не найден, возвращается -1. Вызывающий код (в примере выше функция main), получив результат функции, может идентицировать, что строка найдена или, наоборот, не найдена в базе данных.

В то же время подобный подход не всегда может использоваться. Например, если функция возвращает температуру в градусах, где валидные значения могут быть как положительными, так и отрицательными, и потенциально могут охватывать весь диапазон значений типа int, то возникнет вопрос, какое именно значение использовать в качестве статуса ошибки.

Если функция возвращает указатель, то здесь все проще - в качестве показателя ошибки или неуспешного выполнения можно возвращать значение `NULL`. Например:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define USERS_NUMBER 5      // количество объектов в массиве

// структура условной базы данных
typedef struct
{
    char* users[USERS_NUMBER];
} database;


int find(database* db, char*);

database* create_db(char*);

int main(void){

    // база данных
    database* db = create_db("Tom");
    if(db == NULL) 
    {
        printf("Unable to create database\n");
        return -1;
    }

    // проверяем инициализацию базы данных
    for(size_t i =0; i < USERS_NUMBER; i++)
    {
        printf("%s\n", db->users[i]);
    }
    // освобождаем память
    free(db);
}      
// создание базы данных, инициализированной значением value
database* create_db(char* value)
{
    database* db = 0;
    // если значение value передано и память выделена
     if(value && (db = malloc(sizeof(database))))
    {
        // инициализация массива users начальным значением value
        for(size_t i =0; i < USERS_NUMBER; i++)
        {
            db->users[i] = value;
        }
    }
    return db;
}
```

Здесь определена функция create_db, которая создает объект database и возвращает указатель на него. В качестве параметра функция принимает строку value, которой инициализируются все элементы в массиве users в базе данных. Если параметр value равен NULL или не удалось выделить память для структуры database, то возвращается NULL. Иначе возвращается указатель на объект database.

Значение NULL здесь позволяет легко идентифицировать, что произошла ошибка в процессе создания объекта database.

Иногда необходимо, чтобы функция уведомляла внешний контекст о результатах своей работы на различных ее этапах. В этом случае распространенным решением является возврат из функции статусных кодов. Получив из функции статусный код, вызывающий код может его обработать по своему усмотрению. В качестве статусного кода результата часто используются числовые значения. Например, в Windows Microsoft использует тип `HRESULT`, который фактически представляет 64-разрядное число и применяется для возвращения статусного кода результата.



Так, возьмем следующую программу, которая ищет в файле определенное слово:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
void find(char*, char*, size_t);
void find_word(char*, char*, size_t, FILE*);
 
int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
 
    find(filename, word, size);
}
 
void find_word(char* buffer, char* word, size_t word_size, FILE* file_pointer){
    int found = 0; // индикатор, что слово найдено
    while(fgets(buffer, word_size, file_pointer))
    {
        if(strcmp(word, buffer)==0)
        {
            found = 1;
            break;
        }
    }
    if(found) 
    {
        printf("Success! Word found!\n");
    }
    else
    {
        printf("Word not found...\n");
    }
}
 
void find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
 
    if(!file_name) // если не указано имя файла
    {
        printf("Invalid filename\n");
        return;
    }
    if(!word) // если не указано слово для поиска
    {
        printf("Invalid word for search\n");
        return;
    }
     if(!(file_pointer=fopen(file_name, "r")))  // 
    {
        printf("Unable to open the file\n");
        return;
    }
    if((buffer=malloc(word_size)))      // если память выделена
    {
        find_word(buffer, word, word_size, file_pointer);
        free(buffer);
    }
    else     // если не удалось выделить память
    {
        printf("Error! Unable to locate memory!\n");
    }
    fclose(file_pointer);
}
```



Здесь функция `find()` получает извне имя файла для поиска, слово для поиска и размер слова. Чтобы найти слово, открываем файл и затем выделяем буфер в памяти для считывания данных. Затем вызывается функция `find_word()`, которая считывает символы из файла в буфер и проверяет на их соответствие искомому слову. Здесь есть несколько узловых точек, каждая из которых обрабатывает определенное состояние. Например, если переданное в функцию имя файла не указано, то выводим сообщение об ошибке и выходим из функции:



```c

if(!file_name) // если не указано имя файла
{
    printf("Invalid filename\n");
    return;
}
```



Похожим способом обрабатываются другие ситуации - не указано слово для поиска, не удалось открыть файл, не удалось выделить память для считывания слова. Отдельно стоит сказать про функцию `find_word()`, где для хранения результата пришлось создавать отдельную переменную и в зависимости от ее значения выводим одно или другое сообщение (то есть еще два состояния):



```c

int found = 0; // индикатор, что слово найдено
while(fgets(buffer, word_size, file_pointer))
{
    if(strcmp(word, buffer)==0)
    {
        found = 1;
        break;
    }
}
if(found) 
{
    printf("Success! Word found!\n");
}
else
{
    printf("Word not found...\n");
}
```



Теперь определим статусные коды для каждого состояния и вместо обработки на месте, возвратим статусный код и предоставим обработку вызывающему коду:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef enum{
    FILENAME_INVALID,
    WORD_INVALID,
    FILEOPEN_ERROR,
    ALLOCATION_ERROR,
    WORD_FOUND,
    WORD_NOTFOUND
} status;

status find(char*, char*, size_t);
status find_word(char*, char*, size_t, FILE*);
 
int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
 
    status result = find(filename, word, size);
    switch (result)
    {
        case FILENAME_INVALID:
            printf("Invalid filename\n");
            break;
        case WORD_INVALID:
            printf("Invalid word\n");
            break;
        case FILEOPEN_ERROR:
            printf("Unable to open the file\n");
            break;
        case ALLOCATION_ERROR:
            printf("Unable to allocate memory\n");
            break;
        case WORD_FOUND:
            printf("Success! Word found!\n");
            break;
        case WORD_NOTFOUND:
            printf("Word not found...\n");
            break;
    }
}      
 
status find_word(char* buffer, char* word, size_t word_size, FILE* file_pointer){
    while(fgets(buffer, word_size, file_pointer))
    {
        if(strcmp(word, buffer)==0)
        {
            return WORD_FOUND;
        }
    }
    return WORD_NOTFOUND;
}
 
status find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    status result;
 
    if(!file_name) // если не указано имя файла
    {
        return FILENAME_INVALID;
    }
    if(!word) // если не указано слово для поиска
    {
        return WORD_INVALID;
    }
    if(!(file_pointer=fopen(file_name, "r")))
    {
        return FILEOPEN_ERROR;
    }
    if((buffer=malloc(word_size)))      // если память выделена
    {
        result = find_word(buffer, word, word_size, file_pointer);
        free(buffer);
    }
    else     // если не удалось выделить память
    {
        result = ALLOCATION_ERROR;
    }
    fclose(file_pointer);
    return result;
}
```



Теперь для хранения результата определено перечисление status с 6-ю возможными состояниями. В функции find и find_word в зависимости от условий устанавливаем и возвращаем результат. В функции main, получив статусный код, обрабатываем его в конструкции `switch` - выводим то или иное сообщение.



Таким образом, мы можем отделить логику обработки результата от основного действия функций find/find_word. И в то же время вызывающий код с помощью результата получит статус и должным образом обработает его.



Вместо конструкции switch для обработки статуса можно использовать таблицы, например, изменим код функции main следующим образом:



```c

int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
 
    status result = find(filename, word, size);
    char* status_messages[6] = 
    {
        "Invalid filename\n",
        "Invalid word\n",
        "Unable to open the file\n",
        "Unable to allocate memory\n",
        "Success! Word found!\n",
        "Word not found...\n"
    };
    printf(status_messages[result]);
}
```



Здесь все выводимые сообщения определены в массиве строк status_messages. Поскольку значение перечисления по сути представляет число, причем по умолчанию первая константа в перечислении равна 0, а остальные увеличиваются на единицу, то мы можем использовать статусный код в качестве индекса в массиве для получения нужного сообщения для ее последующего вывода на консоль.



В то же время у возвращения статусных кодов есть и недостатки. Прежде всего функция и вызывающий ее контекст (в примере выше функция main) должны следовать единому API статусных кодов. Кроме того, вызывающий код должен быть осведомлен о смысле и семантике тех или иных кодов, в случае если вызываемую функцию создает другой программист.



Также нелостатком возвращения статусных кодов является тот факт, что функция должна возвращать еще какие-то другие данные. В этом случае можно оборачивать результат функции и статусный код в один общий объект и возвращать его, либо можно использовать выходные параметры (out-параметры), однако второй способ к увеличению количества параметров и может снизить читабельность кода.



### Релевантность статусных кодов



Еще одна проблема, связанная с возвращением информации об ошибки, связана с релевантностью информации. Например, в примере выше, если не удалось выделить память для буфера, то функция find возвращает значение ALLOCATION_ERROR. Имеет ли значение для функции main, что ошибка произошла именно в результате того, что не удалось выделить память? То есть насколько релевантно этот тип статусных кодом для вызывающего кода - функции main? В каждой конкретной ситуации понятие релевантности может различаться. Возможно, для создателя функции main все ошибки будут аналогичны, и он может даже не обрабатывать все отдельные типы статусных кодов:



```c

int main(void){
    char* filename ="test21.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
 
    status result = find(filename, word, size);

    switch (result)
    {
        case WORD_FOUND:
            printf("Success! Word found!\n");
            break;
        case WORD_NOTFOUND:
            printf("Word not found...\n");
            break;
        default: 
            printf("Error occured...\n");
            break;
    }
}
```



В данном случае для всех статусных кодов, отличных от WORD_FOUND и WORD_NOTFOUND выводится одно сообщение об ошибке.



С точки зрения проектировщика функции find мы можем возвращать широкую палитру статусных кодов. Однако если эти статусные коды в принципе не будут использоваться, то нет смысла перегружать функцию возвращением всех этих кодов, а возвращать только такую информацию, которая релевантна для потребителя функции find. Например:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
 
typedef enum{
    ERROR,
    WORD_FOUND,
    WORD_NOTFOUND
} status;

status find(char*, char*, size_t);
status find_word(FILE*, char*, size_t, char*);
 
int main(void){
    char* filename ="test.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
 
    status result = find(filename, word, size);

    switch (result)
    {
        case WORD_FOUND:
            printf("Success! Word found!\n");
            break;
        case WORD_NOTFOUND:
            printf("Word not found...\n");
            break;
        default: 
            printf("Error occured...\n");
            break;
    }
}      

// поиск слова
status find_word(FILE* file_pointer, char* word, size_t word_size, char* buffer){

    while(fgets(buffer, word_size, file_pointer)){
        
        if(strcmp(word, buffer)==0){ 

            return WORD_FOUND;   // если нашли слово
        }
    }
    return WORD_NOTFOUND;        // если не нашли слово
}
 
status find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    status result = ERROR;
 
    // если file_name != NULL и word != NULL и файл октрыт, и память выделена
    if(file_name && word && (file_pointer=fopen(file_name, "r")) && (buffer=malloc(word_size))) 
    {
        result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова
    }
        
    // секция освобождения ресурсов
    if(buffer) free(buffer);
    if(file_pointer) fclose(file_pointer);

    return result;
}
```



В данном случае функция find разом проверяет все 4 ситуации, при которых потенциально может возникнуть ошибка, и если ошибок не возникнет, то выполняет функцию find_word. Уменьшение диапазона возвращаемых статусных кодов кроме большей релевантности в качестве подбочного эффекта имеет уменьшение и упрощение кода, поскольку надо обрабатывать меньше ситуаций, которые могут генерировать разные статусные коды.



В случае с проверкой параметров на null в принципе можно было бы использовать assert:



```c

// если не соблюдаются предусловия, завершаем функцию
assert(file_name!=NULL && "File name is invalid!");
assert(word!=NULL && "Word is invalid!");

// если удалось открыть файл и выделить память
if((file_pointer=fopen(file_name, "r")) && (buffer=malloc(word_size))) 
{
    result = find_word(file_pointer, word, word_size, buffer);
}
```



Однако иногда вообще не требуется какой-то сложной системы статусных кодов и бывает достаточно двух состояний - успех или ошибка. И нередко можно встретить функции, которые возвращают либо true или false, 1 или 0 (-1), вообщем одно из двух значений. Так, в примере выше может быть достаточно, найдено слово или нет. А была выделена память или нет, был ли открыт файл или нет, корректные ли параметры, все это может не играть роли, например:



```c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

int find(char*, char*, size_t);
int find_word(FILE*, char*, size_t, char*);
 
int main(void){
    char* filename ="test32.txt";
    char word[] = "hello";
    size_t size = sizeof(word);
 
    if(find(filename, word, size))
    {
        printf("Success! Word found!\n");
    }
    else
    {
        printf("Word not found...\n");
    }
}      

// поиск слова
int find_word(FILE* file_pointer, char* word, size_t word_size, char* buffer)
{
    while(fgets(buffer, word_size, file_pointer))
    {    
        if(strcmp(word, buffer)==0)
        {
            return 1;   // если нашли слово
        }
    }
    return 0;        // если не нашли слово
}
 
int find(char* file_name, char* word, size_t word_size)
{
    FILE* file_pointer = 0;
    char* buffer = 0;
    int result = 0; // возвращаемый результат
 
    // если не соблюдаются предусловия, завершаем функцию
    assert(file_name!=NULL && "File name is invalid!");
    assert(word!=NULL && "Word is invalid!");

   // если удалось открыть файл и выделить память
    if((file_pointer=fopen(file_name, "r")) && (buffer=malloc(word_size))) 
    {
        result = find_word(file_pointer, word, word_size, buffer); // собственно поиск слова
    }
        
    // секция освобождения ресурсов
    if(buffer) free(buffer);
    if(file_pointer) fclose(file_pointer);

    return result;
}
```



Здесь, если слово найдено, то возвращаем 1, если нет (в том числе если ранее произошла ошибка), то 0. Это еще больше сокращает и упрощает код. В любом случае между проектировщиком функции и ее потребителем должно быть согласие насчет того, какой именно результат и в каком виде должна возвращать функция.

Функция в C может возвращать только одно значение. Тем не менее, что если нам надо получить из функции сразу несколько значений? В этом случае мы можем использовать разные подходы. Основные из них - возвращение комплексного объекта, который инкапсулирует отдельные значения, либо использование выходных параметров.

### Объединение возвращаемых значений

Наиболее простой способ возвратить из функции несколько значений - это определить структуру для хранения этих значений и возвратить ее. Например, нам надо получить из массива минимальное и максимальное значения. Для этого мы могли определить функцию, которая возвращает структуру с двумя значениями:

```c
#include <stdio.h>
#include <assert.h>

typedef struct{
  int min;
  int max;
} MinMax;

MinMax getMinMax(int* array, size_t length)
{
  assert(length >1 && "Array length is invalid");
  MinMax result;
  result.min = array[0];
  result.max = array[0];
  for(size_t i = 0; i < length; i++)
  {
    if(array[i] < result.min) result.min = array[i];
    if(array[i] > result.max) result.max = array[i];
  }
  return result;
}
int main(void)
{
  int array[] = {2, 3, 4, 5, 6, 9};
  size_t length = sizeof(array) / sizeof(int);
  MinMax data = getMinMax(array, length);

  printf("min=%d\n", data.min);     // min=2
  printf("max=%d\n", data.max);     // max=9
}
```

Здесь для возвращения из функции минимального и максимального значения массива определена структура MinMax, которую возвращает функция getMinMax. Это наиболее простой и очевидный способ возвращения нескольких значений. Однако он имеет свои минусы. Прежде всего нам надо специально определять структуру под возвращаемые значения. Во-вторых, при возвращении структуры происходит копирование ее значений в стеке, что увеличивает объем потребляемой памяти.

### Выходные параметры

Другой способ возвратить из функции несколько значений представляют **выходные параметры** (out-параметры). Язык Си как таковой не имеет концепции выходных параметров функции (как например, C#), однако мы можем симулировать выходные параметры с помощью указателей:

```c
#include <stdio.h>
#include <assert.h>

void getMinMax(int* array, size_t length, int* min, int* max)
{
  assert(length >1 && "Array length is invalid");
  *min = array[0];
  *max = array[0];
  for(size_t i = 0; i < length; i++)
  {
    if(array[i] < *min) *min = array[i];
    if(array[i] > *max) *max = array[i];
  }
}
int main(void)
{
  int array[] = {7, 3, 4, 5, 6, 8};
  size_t length = sizeof(array) / sizeof(int);

  int minVal = 0;
  int maxVal = 0;
  getMinMax(array, length, &minVal, &maxVal);
  printf("min=%d\n", minVal);
  printf("max=%d\n", maxVal);
}
```

Общий механизм определения и передачи выходных параметров заключается в следующем. Во-первых, определяем в функции параметры-указатели:

```c
void getMinMax(int* array, size_t length, int* min, int* max)
```

Здесь параметры-указатели min и max как представляют выходные параметры. Внутри функции нам не важны их начальные значения. Наоборот, функция устанавливает их значения.

При вызове функции определяются переменные, и их адреса передаются выходным параметрам:

```c
int minVal = 0;
int maxVal = 0;
getMinMax(array, length, &minVal, &maxVal);
```

В данном случае выходным параметрам min и max передаются соответственно адреса переменных minVal и maxVal.

При использовании выходных параметров нам не обязательно определять дополнительные структуры. Мы избегаем изличнего копирования возвращаемых значений в стеке. Однако выходные параметры рахдувают определение функции, могут снизить ее читабельность, особенно когда таких параметров много.

Иногда необходимо предоставить доступ к данным извне таким образом, чтобы они не могли быть изменены и были доступны только для чтения.

Стандартным решением в этом случае будет определение данных в статической памяти. Данные могут определяться как на этапе компиляции, так и на этапе запуска приложения, и после этого они не изменяются. А для доступа к данным определяется функция, которая возвращает указатель на эти данные. Причем возвращается указатель на константу, чтобы данные не могли быть изменены извне. В общем случае это выглядит следующим образом. На одной стороне - стороне источника данных определяются собственно данные и функция для доступа к ним:

```c
// структура, которая представляет неизменяемые данные
struct Immutable
{
  int x;
  int y;
};

// данные, которые храняться в статической памяти
static struct Immutable data = {11, 22};

// функция, которая возвращает ссылку на данные
const struct Immutable* getData()
{
   return &data;
}
```

На другой стороне - стороне приемника данных вызываем выше определенную функцию и получаем данные в указатель на константу:

```c
const struct Immutable* immut_data;     // чтобы данные не изменились, определяем указатель на константу
immut_data = getData();         // получем данные из источника данных
```

Подобный паттерн иногда называют **Immutable Object** или **Immutable Instance**. Рассмотрим простейший вариант применения. Пусть у нас есть файл **user.h**, где определяется структура используемых данных:

```c
struct User{
  char* name;
  unsigned age;
  char* email;
};
```

Структура User имеет три поля. Это те данные, которые будут представлять неизменяемые данные.

Определим файл **user.c**, который определяет неизменяемые данные и API для доступа к ним:

```c
#include "user.h"

static struct User data = {"Tom", 39, "tom@smail.ru"};
const struct User* getUser(void)
{
    return &data;
}
```

Здесь данные представляют объект data, который представляет структуру User и который размещен в статической памяти. Обратите внимание, что это не константный объект. Он может быть установлен и в процессе работе программы и в принципе даже может быть изменен. Однако он определен с помощью ключевого слова **static**, поэтому напрямую (без применения указателей) из вне файла user.c не виден.

Для доступа к этому объекту определена функция getUser, которая возвращает указатель на константу - адрес объекта data.

И также определим основной файл приложения **app.c**, в котором получаем этот объект:

```c
#include <stdio.h>
#include "user.h"

extern const struct User* getUser(void);

int main(void)
{
  const struct User* user;  // получаемый объект представляет указатель на константу
  user = getUser(); // получаем объект в константу

  printf("name=%s\n", user->name);
  printf("email=%s\n", user->email);
  printf("age=%d\n", user->age);
}
```

Здесь вызываем функцию getUser из файла "user.c" и получаем данные в указатель на константу.

Скомпилируем оба файла в приложение и запустим его:

```bash
c:\C>gcc -Wall -pedantic app.c user.c -o app

c:\C>app
name=Tom
emai=tom@smail.ru
age=39

c:\C>
```

Таким образом, компонент-потребитель данных (код в файле app.c) не должен заботиться об управлении памяти, посольку данные определены в статической памяти. Данный подход может успешно использоваться в многопоточных приложениях, поскольку потоки не изменяют данные, а только читают, и для всех обращающих потоков данные остаются теми же.

Однако здесь также есть недостатки. Например, что если код в файле **app.c** будет получать указатель на неконстантый объект:

```c
struct User* user = getUser();
user->name = "Bob";
```

Хотя при компиляции компиляторы могут выдать предупреждение, но код скомпилируется, нормально отработает, а значения по полученному указателю изменятся.

Кроме того, данные могут измениться на стороне компонента **user.c**. Соответственно в данном случае мы имеем дело с относительной неизменяемостью данных.

Стоит отметить, что мы могли бы пойти дальше в сторону инкапсуляции и определить объект в **user.c** в самой возвращаеющей его функции:

```c
#include <stdio.h>
#include "user.h"

const struct User* getUser(void)
{
    static struct User data = {"Tom", 39, "tom@smail.ru"};
    return &data;
}

void printUser(void){
    const struct User* user;
    user = getUser();
    printf("name=%s\n", user->name);
    printf("emai=%s\n", user->email);
    printf("age=%d\n", user->age);
}
```

И также внутри "user.c" для получения объекта вызываем функцию getUser и получаем указатель на константу.

Нередко возникает необходимость в получении большого набора данных или сложных по структуре данных **фиксированной длины**, которые могут изменяться в процессе работы программы. С одной стороны, мы могли бы определить данные в статической памяти и возвращать указатель на них. Но в том случае потребитель данных может столкнуться с несогласованностью данных - когда он получает одни данные и опирается на них, а тем временем данные где-то извне изменяются. Что особенно может быть характерно для многопточных систем, где разные потоки могут обращаться к общих данным и изменить их. Возвратить эти данные напрямую из функции в виде структуры тоже может быть не самым лучшим вариантом, поскольку структура копируется в стек, а стек ограничен поэтому для больших данных данных такой способ не очень подходит.

И в качестве решения здесь может быть определение буфера для получения данных на стороне компонента-приемника данных. Компонент-источник данных определяет функцию, которая принимает данный буфер и копирует в него данные. В общем случае это выглядит следующим образом. Код компонента-источника данных:

```c
#define DATA_SIZE 256   // фиксированное количество данных
// некоторые данные
static char data[DATA_SIZE]
// функция, которая получает от приемника буфер и копирует в него данные
void getData(char* buffer)
{
  memcpy(buffer, data, DATA_SIZE);
}
```

Код компонента-приемника данных:

```c
// буфер, который передается источнику и в который копируются данные
static char buffer[DATA_SIZE]
// передаем буфер для копирования в него
getData(buffer);
```

Код обоих компонентов копирует набор данных, размер которого заранее известен, и для обоих компонентов он совпадает, поэтому не существует проблемы, что будет скопированно меньше или больше байтов.

К слову, похожий паттерн применяется, в частности, в библиотечной функции **fgets**, в которую передается буфер для считывания данных из файла.

Рассмотрим небольшой пример. Пусть у нас есть заголовочный файл **user.h**, где определена структура User, которая представляет данные:

```c
struct User{
  char* name;
  unsigned age;
};

#define DATA_COUNT 5 // размер данных
```

Кроме того, здесь определена константы DATA_COUNT, которая будет представлять количество структур в наборе данных.

Пусть также определен файл **user.c**, который определяет источник данных:

```c
#include <stdio.h>
#include <string.h>
#include "user.h" 

// условные данные
static struct User data[DATA_COUNT] = {{"Tom", 39}, {"Bob", 43}, {"Sam", 29}, {"Alice", 35}, {"Kate", 28}};

void getUsers(struct User* buffer)
{
    // копируем в буфер данные
    memcpy(buffer, data, DATA_COUNT * sizeof(struct User));
}
```

Прежде всего здесь определены сами данные в виде массива структур User размером DATA_COUNT

Функция getUsers получает в качестве параметра буфер, в который будут копироваться данные. В самой функции копируем данные с помощью библиотечной функции **memcpy**. И поскольку данные фиксированного размера, то ожидается, что буфер будет той же длины, что и массив с данными.

И пусть у нас есть основной файл программы - **app.c**, в котором получаем данные:

```c
#include <stdio.h>
#include "user.h"

extern void getUsers(struct User*);

int main(void)
{
  // определяем буфер для данных
  struct User buffer[DATA_COUNT];

  // получаем данные
  getUsers(buffer);

  for(int i =0; i < DATA_COUNT; i++)
  {
    printf("%s - %u\n", buffer[i].name, buffer[i].age);
  }
}
```

Здесь вызываем функцию getUsers из файла **user.c** и передаем в нее буфер. В данном случае буфер определен как автоматическая переменная, которая хранится в стеке. Но это не столь важно, подобный буфер может быть определен и в статической и в динамической памяти. И после выполнения функции буфер будет содержать скопированные данные. Пример работы программы:

```c
c:\C>gcc -Wall -pedantic app.c user.c -o app & app
Tom - 39
Bob - 43
Sam - 29
Alice - 35
Kate - 28

c:\C>
```

Таким образом, компонент-приемник может быстро и с помощью одного параметра получить большие и сложные по структуре данные. Приемнику данных достаточно предоставить буфер нужной длины. Если к данным обращаются несколько потоков, то каждый предоставляет свой собственный буфер и дальше работает с этим буфером, поэтому данный подход безопасен при использовании в многопоточных программах. Однако компоненту-приемнику необходимо знать размер данных, что не всегда возможно.

Иногда бывает необходимо получить большие или сложные по структуре данных **неизвестной длины**, которые могут изменяться в процессе работы программы. С одной стороны, мы могли бы определить данные в статической памяти и возвращать указатель на них. Но в том случае потребитель данных может столкнуться с несогласованностью данных - когда он получает одни данные и опирается на них, а тем временем данные где-то извне изменяются. Что особенно может быть характерно для многопточных систем, где разные потоки могут обращаться к общих данным и изменить их. Возвратить эти данные напрямую из функции в виде структуры тоже нельзя, поскольку размер данных неизвестен, а стек ограничен по размеру.



Определение буфера на стороне приемника данных не является решением, поскольку компонент-приемник данных должен выполнить дополнительные действия, чтобы узнать количество данных. Но даже если он узнает количество данных, оно может измениться к тому моменту, когда он выполнит непосредственно запрос данных.



Решением может быть определение буфера для данных на стороне компонента-источника данных, поскольку только компонент-источник знает точный размер данных в текущий момент. Компонент-источник данных также определяет функцию, которая возвращает буфер со скопированными данными и его размер. А компонент-приемник вызывает функцию и получает буфер и его размер.



В плане реализации могут быть вариации, как возвращать буфер и количество считанных данных. Можно возвращать через выходные параметры, либо как результат функции. В общем случае возвращение черех выходные параметры выглядит следующим образом. Код компонента-источника данных:



```c

#define DATA_SIZE 256
// некоторые данные
static char data[DATA_SIZE]
// функция, копирует в буфер данные и возвращает через параметры буфер и его размер
void getData(char** buffer, int* size)
{
  *size = DATA_SIZE;
  *buffer = malloc(size);
   memcpy(*buffer, data, size);  // копируем данные
}
```



Компонент-источник данных выделяет для буфера некоторую область в динамической памяти и в нее копирует данные. Буфер и его размер возвращаются через выходные параметры. Обратите внимание, что первый параметр - buffer определен как указатель на указатель. То есть грубо говоря в функцию будет передаваться адрес указателя. И по этому адресу сохраняется указатель на выделенную память.



Код компонента-приемника данных:



```c

// указатель для буфера
char* buffer;
int size;
getData(&buffer, &size);    // получаем данные и их размер

// работа с буфером

free(buffer);   // освобождаем память
```



Компонент-приемник вызывает функцию для получения данных и передает в нее указатель для адреса буфера и адрес переменной-размера буфера. После получения и работы с данными компонент-приемник освобождает память (так как буфер выделен в динамической памяти).



В качестве альтернативы можно возвращать буфер и размер данных как результат функции в виде структуры:



```c

/* Общая структура результата */
struct DataList{
    char* buffer;   // буфер данных
    size_t size;    // размер данных
}

/* Код источника-приемника данных*/
#define DATA_SIZE 256
// некоторые данные
static char data[DATA_SIZE]
// функция, копирует в буфер данные и возвращает через структуру DataList
struct DataList getData()
{
    struct DataList result;
    result.size = DATA_SIZE;
    result.buffer = malloc(size);
    memcpy(result.buffer, data, result.size);  // копируем данные
}

/***********************************/
/* Код компонента-приемника данных*/

struct DataList result = getData();    // получаем данные и их размер

// работа с буфером

free(result.buffer);   // освобождаем память
```



Подобный подход удобен в многопоточных системах, так как каждый поток, получив данные, работает с ними независимо от других потоков, и можно не беспокоиться, что данные извне где-то изменяться. Соотвественно достигается согласованность данных, пока с ними работает компонент-приемник данных. В то же время компонент-приемник должен следить за освобождением памяти. Рассмотрим данные варианты на небольшом примере.



### Возвращение буфера и размера данных через результат функции



Пусть у нас есть заголовочный файл **user.h**, где определена структура User, которая представляет данные:



```c

// структура представляет данные
struct User{
  char* name;
  unsigned age;
};
// структура представляет возвращаемый результат
struct UsersList
{
  struct User* buffer;
  size_t count;
};
```



Кроме того, здесь определена структура UsersList, которая будет использоваться для определения результата. Она хранит буфер для считывания структур User и количество считанных структур.



Пусть также определен файл **user.c**, который определяет компонент-источник данных:



```c

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "user.h" 

// условные данные
static struct User data[] = {{"Tom", 39}, {"Bob", 43}, {"Sam", 29}, {"Alice", 35}, {"Kate", 28}};

struct UsersList getUsers()
{
    // определяем результат
    struct UsersList result;
    // общее количество данных в байтах
    size_t data_size = sizeof(data);
    // получаем количество структур
    result.count = data_size / sizeof(struct User);
    // выделяем память для буфера
    result.buffer = malloc(data_size);
    // если не удалось выделить память
    assert(result.buffer!=NULL && "Unable to allocate a memory");
    // копируем в буфер данные
    memcpy(result.buffer, data, data_size);
    // возвращаем структуру
    return result;
}
```



Прежде всего здесь определены сами данные в виде массива data, которые хранит набор структур User и размер которого неизвестен извне.



Функция getUsers определяет возвращаемый результат в виде структуры UsersList. В самой функции получаем размер данных и количество структур. Устанавливаем у возвращаемой структуры поле count - количество структур в буфере. Далее выделяем динамическую память для буфера и сохраняем адрес указателя в поле buffer в возвращаемой структуре и с помощью библиотечной функции **memcpy** копируем данные в выделенную динамическую память. В конце возвразаем структуру UsersList



И пусть у нас есть основной файл программы - **app.c**, в котором получаем данные:



```c

#include <stdio.h>
#include <stdlib.h>
#include "user.h"

extern struct UsersList getUsers();

int main(void)
{
  // получаем данные
  struct UsersList result = getUsers();

  // работа с полученными данными
  for(int i =0; i < result.count; i++)
  {
    printf("%s - %u\n", result.buffer[i].name, result.buffer[i].age);
  }
   
  free(result.buffer); // освобождаем память буфера
}
```



Здесь вызываем функцию getUsers из файла **user.c** и получаем из нее результат в виде структуры UsersList. В итоге ее поле buffer будет содержать адрес буфера со скопированными данными, а поле count - количество структур в наборе. Поскольку буфер выделен в динамической памяти, то в конце освобождаем его память. Пример работы программы:



```c

c:\C>gcc -Wall -pedantic app.c user.c -o app & app
Tom - 39
Bob - 43
Sam - 29
Alice - 35
Kate - 28

c:\C>
```



### Возвращение буфера и размера данных через выходные параметры



Другой вариант возвращения данных представляют выходные параметры. Так, пусть в компоненте-источнике данных- в файле **user.c** определен следующий код:



```c

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "user.h" 

// условные данные
static struct User data[] = {{"Tom", 39}, {"Bob", 43}, {"Sam", 29}, {"Alice", 35}, {"Kate", 28}};

void getUsers(struct User** buffer, size_t* count)
{
    size_t data_size = sizeof(data);
    // получаем количество структур
    *count = data_size / sizeof(struct User);
    // выделяем память для буфера
    *buffer = malloc(data_size);
    // если не удалось выделить память
    assert(*buffer!=NULL && "Unable to allocate a memory");
    // копируем в буфер данные
    memcpy(*buffer, data, data_size);
}
```



Также здесь определены сами данные в виде массива структур User, размер которого неизвестен извне.



Функция getUsers получает в качестве параметра адрес на указатель, в который будет сохраняться указатель на буфер в динамической памяти. Второй параметр представляет указатель на количество структур. В самой функции получаем размер данных и количество структур. Устанавливаем значения указателя count, которые указывает на количество структур в буфере. Далее выделяем динамическую память для буфера и сохраняем адрес указателя на выделенную память в указатель, адрес которого передан в buffer. В конце с помощью библиотечной функции **memcpy** копируем данные в выделенную динамическую память.



И пусть у нас есть основной файл программы - **app.c** определяет следующий компонент-приемник данных:



```c

#include <stdio.h>
#include <stdlib.h>
#include "user.h"

extern void getUsers(struct User**, size_t*);

int main(void)
{
  // определяем указатель на полученный буфер
  struct User* buffer;
  size_t count = 0;
  // получаем данные
  getUsers(&buffer, &count);

  for(int i =0; i < count; i++)
  {
    printf("%s - %u\n", buffer[i].name, buffer[i].age);
  }
   
  free(buffer); // освобождаем память буфера
}
```



Здесь вызываем функцию getUsers из файла **user.c** и передаем в нее адрес указателя на буфер и адрес переменной count. После выполнения функции указатель на буфер будет содержать адрес буфера со скопированными данными, а переменная count - количество структур в наборе. И в конце также освобождаем память буфера.



### Возвращение буфера через выходной параметр и размера данных через результат



Другая часто используемая схема представляет возвращение буфера через выходной параметр, а количество считанных данных через результат функции. Например, на стороне компонента-источника данных в файле **user.c** определим следующий код:



```c

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "user.h" 

// условные данные
static struct User data[] = {{"Tom", 22}, {"Bob", 43}, {"Sam", 29}, {"Alice", 35}, {"Kate", 28}};

size_t getUsers(struct User** buffer)
{
    size_t data_size = sizeof(data);
    // получаем количество структур
    size_t count = data_size / sizeof(struct User);
    // выделяем память для буфера
    *buffer = malloc(data_size);
    // если не удалось выделить память
    assert(*buffer!=NULL && "Unable to allocate a memory");
    // копируем в буфер данные
    memcpy(*buffer, data, data_size);
    // в качестве результата возвращаем количество структур
    return count;
}
```



Теперь функция getUsers возвращает количество данных напрямую в качестве результата.



В компоненте-приемника данных - в файле**app.c** получим переданные данные:



```c

#include <stdio.h>
#include <stdlib.h>
#include "user.h"

extern size_t getUsers(struct User**);

int main(void)
{
  // определяем указатель на полученный буфер
  struct User* buffer;
  // получаем данные
  size_t count = getUsers(&buffer);

  for(int i =0; i < count; i++)
  {
    printf("%s - %u\n", buffer[i].name, buffer[i].age);
  }
   
  free(buffer); // освобождаем память буфера
}
```

Для упрощения организации программы ее код обычно разбивается на отдельные модули или отдельные файлы. Отдельный файл/модуль обычно содержит связанный функционал, который выполняет некоторую общюю работу. Однако при разделении функционала программы на отдельные файлы мы можем столкнуться с рядом проблем.

Частая встречающаяся проблема представляет дублирование глобальных идентификторов в разных файлах. Например, пусть у нас есть файл (модуль) **user.c**:

```c
#include <stdio.h>

// условные данные
char* username = "tom@smail.com";

void printUserName()
{
    printf("UserName: %s\n", username);
}
void resetUserName()
{
    username = "Undefined";
}
```

Здесь определена глобальная переменная username и две функции для ее вывода на консоль и сброса в некоторое стандартное значение. И допустим, у нас есть основной файл программы **app.c**, который использует модуль "user.c":

```c
#include <stdio.h>

char* username = "Tom";

extern void resetUserName();
void printUserName()
{
    printf("Name: %s\n", username);
}

int main(void)
{
  printUserName();
  resetUserName();
}
```

Здесь определены глобальная переменная и функция с теми же именами, что и в модуле "user.c", но немного иным содержимым. Попробуем скомпилировать оба файла, например, с помощью **gcc**

```bash
gcc -Wall -pedantic app.c user.c -o app
```

И в процессе компиляции мы столкнемся с ошибкой. В зависимости от среды и компилятора конкретный вывод ошибки может отличаться, но в любом случае ее суть будет в том, что у нас дублируются глобальные идентификаторы в обоих файлах - глобальная переменная username и функция printUserName.

Вторая проблема касается несанкционированного доступа к функционалу. Так, в коде "app.c" мы вызываем функцию resetUserName для сброса имени. Однако здесь мы можем задаться вопросом, а должен ли внешний код иметь возможность выполнять эту функцию? В зависимости от задачи и ситуации ответ может быть разным. Но, допустим, мы НЕ хотим, чтобы внешний код видел эти данные. Особенно если модуль "user.c" создаем мы, а использует его какое-то внешнее приложение, где мы вообще можем не знать, в каком случае эта функция будет вызываться.

Обе проблемы ставят нас перед задачей **инкапсуляции** функционала в модуле и предоставления внешнему коду доступа только к определенным ограниченным возможностям модуля.

### Определение API

В общем случае при определении модуля прежде всего определяется **API** (Application Program Interface) - тот функционал, который будет виден извне и который может использоваться во внешнем коде. Объявления функций и типов, которые входят в API, выносятся в заголовочный файл, для его подключения во внешнем коде. Остальной функционал, который не попадает в API, определяется с модификатором **static**, что позволяет сделать этот функционал доступным только в рамках файла определения.

Например, нам надо определить модуль для вывода текстового файла на консоль. Вначале определим API и для этого создадим следующий файл **file_printer.h**:

```c
// функция вывода файла на консоль
void printFile(char*);
```

API довольно простое - определяем функцию printFile, которая принимает имя файла.

Далее определим модуль поиска в файле - файл **file_printer.c**, где будет располагаться реализация вывода файла на консоль:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include "file_printer.h"

// получаем длину файла
// функция не входит в API, поэтому определена со словом static
static int getFileLength(FILE* fp)
{
    fseek(fp, 0, SEEK_END);
    int file_length = ftell(fp);
    return file_length;
}
// считываем файл в buffer
// функция не входит в API, поэтому определена со словом static
static void readFile(FILE* fp, char* buffer, int file_length)
{
    fseek(fp, 0, SEEK_SET);
    int read_elements = fread(buffer, 1, file_length, fp);
    buffer[read_elements] = '\0';   // устанавливем концевой нулевой байт для строки
}
// вывод файла на консоль
// Функция printFile входит в API, поэтому определена без слова static
void printFile(char* filename)
{
    FILE* fp = 0; // инициализируем нулем
    char* text = 0;         // инициализируем нулем 

    assert(filename && "Invalid file name"); // если некорректное имя файла, прерываем программу

    fp = fopen(filename, "r");  // открываем файл
    assert(fp && "Unable to open file!\n"); // если не удалось открыть файл, прерываем программу

    int file_length = getFileLength(fp);  // получаем длину файла
    if(file_length > 0)
    {
        text = malloc(file_length);
        if(text)    // если удалось выделять память
        {
            readFile(fp, text, file_length);  // считываем файл
            printf("%s\n",text);

            free(text); // освобождаем память
            text = 0;   // сбрасываем значение указателя в ноль
        }
    }
    fclose(fp);     // закрываем файл
    fp = 0;         // сбрасываем значение указателя в ноль
}
```

Здесь определена реализация функции printFile для вывода файла на консоль. Однако в своей сущности она использует две другие функции. Так, чтобы вывести файл на консоль, нам надо сначала получить его длину с помощью функции getFileLength и затем считать в буфер полученной длины файл с помощью функции readFile. Использование этих функций в отрыве от функции printFile не имеет смысла. Внешний код не должен к ним обращаться, поэтому они не входят в API и определены с помощью ключевого слова **static**

И определим основной файл программы **app.c**, который будет использовать вывод файла на консоль:

```c
#include <stdio.h>
#include "file_printer.h"

int main(void)
{
    char* filename ="test.txt";
    printFile(filename);
}
```

Для использования API подключаем его определение в файле "file_printer.h". Таким образом, для внешнего кода - файла "app.c" существует только функция printFile, а ее реализация для него не важны.

Таким образом, мы можем обеспечить инкапсуляцию функционала и отделить определение API от его реализации.

Модуль может хранить некоторое глобальное состояние - некоторый набор общих данных, над которыми функции модуля могут производить различные операции. Внешний код может вызывать эти функции и таким образом выполнять различные действия над состоянием модуля. Если состоние модуля не зависит от внешнего кода, то это состояние определяется в виде глобальных переменных и констант, к которым применяется ключевое слово **static**.

Таким образом, доступ к этому состоянию ограничивается текущим модулем. А функции, которые выполняют операции с этим состоянием, будет определять API модуля и объявляются в заголовочном файле. Благодаря этому внешний код посредством функций может выполнять действия над состоянием модуля. А модуль внутри функции может проконтролировать эти действия. Формально это выглядело бы следующим образом:

```c
/* API (заголовочный файл) */
// условные операции с состоянием
int addNext(int value);


/* Реализация в модуле */
// условное состояние
static int sum = 0;

// реализация API
int addNext(int value)
{
  sum = sum + value;
  return sum;
}

/* Внешний код, который обращается к API модуля */
int result;
result = addNext(10);
result = addNext(20);
```

Таким образом, состояние модуля полностью отделено от внешнего кода, который производит с ним операции. Если для инициализации состояния нужны некоторые действия, например выделение памяти и т.д., а после работы с состоянием освобождение ресурсов, то все эти действия ложаться на модуль.

Рассмотрим небольшой пример. Сначала определим API. Для этого создадим следующий файл **database.h**:

```c
// вывод одного объекта по индексу
extern void printUser(int); 
// вывод всех объектов
extern void printUsers();
```

Здесь определены объявления функций printUser и printUsers для вывода одного объекта по индексу и всех объектов из условной базы данных соответственно.

Далее определим реализацию этих функций в файле **database.c**:

```c
#include <stdio.h>
#include "database.h" 

#define DATA_MAX_SIZE 5
// условные данные
static char* data[DATA_MAX_SIZE] = {"Tom", "Bob", "Sam", "Alice", "Kate"};

void printUser(int index)
{
    if(index > -1 && index < DATA_MAX_SIZE)
        printf("%s\n",data[index]);
    else
        printf("User not found\n");
}

void printUsers()
{
    printf("Users List\n");
    for(size_t i =0; i < DATA_MAX_SIZE; i++)
    {   
        printf("%s\n",data[i]);
    }
}
```

В данном файле/модуле определено общее, разделяемое состояние в виде массива указателей char*, то есть строк. Это состояние не зависит от внешнего кода и скрыто от него применением оператора **static**. То есть массив data доступен только в текущем модуле. А внешний код может обращаться к нему только опосредственно - через функции.

Для тестирования определим файл **app.c** со следующим кодом:

```c
#include <stdio.h>
#include "database.h"

int main(void)
{
    printUser(1);
    printUsers();
}
```

Для файла "app.c" состояние модуля database.c - массив data доступно только через функции API модуля, а напрямую недоступно.

Сокмпилируем и запустим программу:

```bash
c:\C>gcc -Wall -pedantic app.c database.c -o app & app
Bob

Users List
Tom
Bob
Sam
Alice
Kate
```

Инкапсуляция состояния в модуле и опосредованный доступа к нему через функции - очень простой прием, который прекрасно работает, когда есть только один клиент, который обращается к модулю. Однако в многопоточных программах могут возникнуть проблемы, поскольку несколько потоков могут одновременно обращаться к состоянию, и в этом случае может потребоваться использование мьютексов или иных инструментов для разграничения доступа потоков к общему ресурсу.

В определенных ситуациях состояние модуля может полностью зависеть от клиента - внешнего кода, который к этому состоянию обращается. То есть модуль определяет структуру состояния и API для взаимодействия с состоянием, а содержимое и жизненный цикл состояния определяет клиент. При этом модуль хочет скрыть от клиента реализацию API для взаимодействия с состоянием. Например, пользователь создает на некотором сервисе учетную запись. Учетная запись полностью зависит от пользователя, пользователь может удалить ее. Однако интерфейс, API для управления учетной записью определяет сервис или модуль. И детали этого API скрыты от пользователя.

Если мы имеем дело только с одним клиентом, который обращается к модулю, то такое состояние можно хранить и непосредственно в модуле. Однако если к модулю одновременно обращаются несколько клиентов, в частности, в многопточных программах, то хранение состояния в модуле не работает. В этом случае в качестве решения объект состояния хранится на стороне клиента, например, в виде структуры. Для взаимодействия с этим состоянием модуль предоставляет функции, в которые клиент передает указатель на структуру - объект состояния. При этом модуль также предоставляет функции для создания и удаления состояния, но вызывает их клиент. То есть жизненный цикл объекта состояния полностью определяет клиент.

Примерная реализация:

```c
/* API модуля (заголовочный файл) */
// структура, которая представляет состояние
struct INSTANCE
{
  int x;
  int y;
};

// создание состояния
struct INSTANCE* createInstance();

// некоторые действия над состоянием
void operateOnInstance(struct INSTANCE* inst);
// удаление состояния
void destroyInstance(struct INSTANCE* inst);

/* Реализация в модуле */
struct INSTANCE* createInstance()
{
  struct INSTANCE* inst;
  inst = malloc(sizeof(struct INSTANCE));
  return inst;
}

void operateOnInstance(struct INSTANCE* inst)
{
  // некоторая работа с состоянием
}

void destroyInstance(struct INSTANCE* inst)
{
  free(inst);
}

/* код клиента */
struct INSTANCE* inst;
inst = createInstance();    // создаем состояние
operateOnInstance(inst);    // работаем с состоянием
destroyInstance(inst);      // работу закончили - удаляем состояние
```

Таким образом, код становится более сложным. Кроме того, модуль должен определить функции для создания и удаления состояния, а клиент должен не забыть их вызвать. Однако такой подход удобен в многопоточных программах со множеством клиентов, так как каждый клиент хранит свое собственную копию состояния. В тоже время очевидно, что он подойдет не для всех задач. Например, если несколько клиентов (потоков) захотят записать данные в один и тот же файл, то естественно они не смогут это сделать, поскольку файл один. Подобный паттерн еще называют **Client-Dependent Instance** или **Caller-Owned Instance**

В качестве небольшого примера определим заголовочный файл **account.h**, который будет хранить API модуля account:

```c
#define STR_SIZE 16
struct Account
{
    char username[STR_SIZE];
    char password[STR_SIZE];
};

struct Account* createAccount(char* username, char* pass);
void printName(struct Account* acc);
void deleteAccount(struct Account* acc);
```

Здесь состояние определено в виде структуры Account, которая представляет условную учетную запись и определяет два поля - для хранения соответственно имени пользователя и пароля.

Также API определяет три функции. Функция createAccount принимает логин и пароль пользователя и возвращает указатель на структуру Account. Функция printName получает указатель на структуру Account и выполняет с ней некоторые действия (выводит имя пользователя на консоль). И функция deleteAccount удаляет структуру Account.

В файле **account.c** реализуем API модуля:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "account.h"

struct Account* createAccount(char* username, char* pass)
{
  struct Account* acc = malloc(sizeof(struct Account));
  memcpy(acc->username, username, STR_SIZE);
  memcpy(acc->password, pass, STR_SIZE);
  return acc;
}

void printName(struct Account* acc)
{
  if(acc) printf("User Name: %s\n", acc->username);
}

void deleteAccount(struct Account* acc)
{
  if(acc) free(acc);
  acc = 0;
}
```

В данном случае в функции createAccount выделяем память под структуру Account, а в функции deleteAccount освобождаем память.

В файле **app.c** определим клиент, который будет хранить объект состояния и обращаться к API модуля account:

```c
#include "account.h"

int main(void)
{
    struct Account* acc = createAccount("tom smith", "qwerty"); // создаем состояние
    printName(acc);     // операции с состоянием
    deleteAccount(acc); // удаляем состояние
}
```

Пример компиляции и консольный вывод программы:

```bash
c:\C>gcc -Wall -pedantic app.c account.c -o app & app
User Name: tom smith

c:\C>
```

Прошлой теме было рассмотрено управление состоянием модуля на клиенте. В частности, в заголовочном файле **account.h** было определено следующее API модуля:

```c
#define STR_SIZE 16
struct Account
{
    char username[STR_SIZE];
    char password[STR_SIZE];
};

struct Account* createAccount(char* username, char* pass);
void printName(struct Account* acc);
void deleteAccount(struct Account* acc);
```

Здесь определено состояние определено в виде структуры Account, которая представляет условную учетную запись и определяет два поля - для хранения соответственно имени пользователя и пароля.

Также API определяет три функции. Функция createAccount принимает логин и пароль пользователя и возвращает указатель на структуру Account. Функция printName получает указатель на структуру Account и выполняет с ней некоторые действия (выводит имя пользователя на консоль). И функция deleteAccount удаляет структуру Account.

В файле **account.c** была определена реализация API модуля:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "account.h"

struct Account* createAccount(char* username, char* pass)
{
  struct Account* acc = malloc(sizeof(struct Account));
  memcpy(acc->username, username, STR_SIZE);
  memcpy(acc->password, pass, STR_SIZE);
  return acc;
}

void printName(struct Account* acc)
{
  if(acc) printf("User Name: %s\n", acc->username);
}

void deleteAccount(struct Account* acc)
{
  if(acc) free(acc);
  acc = 0;
}
```

В данном случае в функции createAccount выделяем память под структуру Account, а в функции deleteAccount освобождаем память. Функция printName имитирует некоторую работу с состоянием - вывод поля структуры Account на консоль.

В файле **app.c** был определен клиент, который будет хранить объект состояния и обращаться к API модуля account:

```c
#include "account.h"

int main(void)
{
    struct Account* acc = createAccount("tom smith", "qwerty"); // создаем состояние
    printName(acc);     // операции с состоянием
    deleteAccount(acc); // удаляем состояние
}
```

Хотя этот пример прекрасно работает. Но что, если мы обратимся на клиенте к полям структуры:

```c
#include <stdio.h>
#include "account.h"

int main(void)
{
    struct Account* acc = createAccount("tom smith", "qwerty");

    printf("%s\n", acc->password); // обращаемся к полю password

    deleteAccount(acc);
}
```

Этот код прекрасно работает. При данной организации клиент может напрямую обращаться к полям структуры состояния. Однако это может быть нежелательно - клиент может нежелательным образом изменить состояние. Кроме того, это девальвирует API модуля. Поскольку если мы можем обращаться напрямую к полям состояния, зачем нам API?

В ряде языков программирования есть приватные переменные в классах. В Си мы также можем эмулировать подобную возможность, чтобы из внешнего кода нельзя было обращаться к полям структуры. И тут есть два варианта. Можно просто в заголовочном файле просто объявить структуру без реализации, либо объявить в заголовочном файле указатель на структуру. Рассмотрим оба случая. И сначла пропишем реализацию структуры Account непосредственно в файле модуля **account.c**:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "account.h"

#define STR_SIZE 16
struct Account
{
    char username[STR_SIZE];
    char password[STR_SIZE];
};

struct Account* createAccount(char* username, char* pass)
{
  struct Account* acc = malloc(sizeof(struct Account));
  memcpy(acc->username, username, STR_SIZE);
  memcpy(acc->password, pass, STR_SIZE);
  return acc;
}

void printName(struct Account* acc)
{
  if(acc) printf("User Name: %s\n", acc->username);
}

void deleteAccount(struct Account* acc)
{
  if(acc) free(acc);
  acc = 0;
}
```

### Объявление структуры без определения

Первый способ инкапсуляции полей структуры представляет объявление структуры без ее определения в API модуля. Так, изменим API в файле **account.h**

```c
struct Account; // только объявление структуры
struct Account* createAccount(char* username, char* pass);
void printName(struct Account* acc);
void deleteAccount(struct Account* acc);
```

Здесь указано только объявлена структура без реализации. Теперь из кода клиента мы не сможем напрямую обращаться к полям структуры:

```c
#include <stdio.h>
#include "account.h"

int main(void)
{
    struct Account* acc = createAccount("tom smith", "qwerty");

    printf("%s\n", acc->password); // ! Ошибка

    deleteAccount(acc);
}
```

При попытке обратиться к полям структуры на клиенте мы получим ошибку, поскольку клиент не знает реализацию структуры Account.

### Объявление указателя на структуру

Второй способ скрытия реализации структуру в принипе аналогичен и подразумевает определения указателя на структуру. Так, изменим API в файле **account.h** следующим образом:

```c
typedef struct Account* UserAccount;    // указатель на структуру
struct Account* createAccount(char* username, char* pass);
void printName(struct Account* acc);
void deleteAccount(struct Account* acc);
```

Здесь только определен указатель на структуру, в качестве псевдонима которого выступает тип UserAccount. Но из этого определения клиент опять же не узнает о содержимом структуры. На клиенте в файле **app.c** мы могли бы ссылаться на указатель структуры как на тип UserAccount

```c
#include <stdio.h>
#include "account.h"

int main(void)
{
    UserAccount acc = createAccount("Tom Smith", "qwerty");

    printf("%s\n", acc->password); // ! Ошибка

    deleteAccount(acc);
}
```

Но при попытке обратиться к отдельным полям структуры мы опять же столкнемся ошибкой. И таким образом, взаимодействовать со структурой мы можем только через API модуля.

Иногда необходимо предоставить множеству клиентов/потоков доступ к одному и тому же состоянию, которое зависит от клиента. То есть каждый клиент может создавать объект состояния. Однако клиенты также могут работать с уже имеющимся состоянием, которое созадали другие клиенты.



В этом случае решением будет хранение состояния внутри модуля в виде списка объектов (поскольку каждый клиент может создавать свой объет состояния). Модуль также предоставляет клиенту некоторый API - набор функций для работы с состоянием. Клиент создает новый объект состояния или получает уже имеющийся и передает его в функции API для работы с ним. Причем при создании объекта состояния клиент должен предоставить некоторый идентификатор, который сохраняется в объекте состояния. Благодаря идентификатору можно разграничить данные объект состояния от других и проверить его наличие. Если объект с идентификатором уже есть, то клиент просто получает уже имеющийся объект. Если объект с идентификатором отсутствует, то он создается.



Формально паттерн можно представить следующим образом:



```c

/* API модуля (заголовочный файл) */
// структура, которая представляет состояние
struct INSTANCE
{
  int x;
  int y;
};

// некоторый набор идентификаторов для объектов состояния
#define INSTANCE_TYPE_A 1
#define INSTANCE_TYPE_B 2
#define INSTANCE_TYPE_C 3

// Получем объект состояния, для этого в функцию передаем идентификатор объекта
struct INSTANCE* openInstance(int id);

// некоторая работа с состоянием
void operateOnInstance(struct INSTANCE* inst);

// освобождаем обхект
void closeInstance(struct INSTANCE* inst);

/* Реализация в модуле*/
// максимальное число объектов состояния
#define MAX_INSTANCES 4

struct INSTANCELIST
{
  struct INSTANCE* inst;
  int count;
};
// список, который хранит все объекты состояния
static struct INSTANCELIST list[MAX_INSTANCES];

// создаем объект состояния
struct INSTANCE* openInstance(int id)
{
  if(list[id].count == 0)
  {
    list[id].inst =  malloc(sizeof(struct INSTANCE));
  }
  list[id].count++;
  return list[id].inst;
}

void operateOnInstance(struct INSTANCE* inst)
{
  // некоторая работа с состоянием
}
// получаем состояние по id
static int getInstanceId(struct INSTANCE* inst)
{
  int i;
  for(i=0; i<MAX_INSTANCES; i++)
  {
    if(inst == list[i].inst)
    {
      break;
    }
  }
  return i;
}
// удаляем состояние
void closeInstance(struct INSTANCE* inst)
{
  int id = getInstanceId(inst);
  list[id].count--;
  if(list[id].count == 0)
  {
    free(inst);
  }
}

/* Возможные клиенты, которые работают с состоянием */
// клиент 1
struct INSTANCE* inst = openInstance(INSTANCE_TYPE_B); // получаем объект
operateOnInstance(inst);    // работа с объектом
closeInstance(inst);        // освобождение объекта

// клиент 2
struct INSTANCE* inst = openInstance(INSTANCE_TYPE_B); // получаем объект
operateOnInstance(inst); // работа с объектом
closeInstance(inst);        // освобождение объекта
```

 

Клиент получает объект в указатель INSTANCE, вызывая фукцию openInstance. Если объект INSTANCE не существует, то он создается. Если существует, то возвращается. Причем функция фукцию openInstance также увеличивает счетчик клиентов, которые в текущий момент обращаются к объекту состояния. Получив объект INSTANCE, для работы с ним клиент передает его в функции API. Завершив работу, клиент удаляетобъект с помощью вызова функции closeInstance. Функция closeInstance учитывает количество обративнихся к этому объекту клиентов. И если клиентов, которые работают с этим объектом уже нет, то объект удаляется.



Таким образом, множество клиентов могут одновременно обращаться к единому разделяемому состоянию. Такой паттерн еще называют **Shared Instance**



Примером применения паттерна являются функции для работы с файлами в **stdio.h**. Так, функция **fopen** открывает файл, а функция **fclose()** закрывает файл. Между вызовами этих функцию могут вызываться функции для работы с файлом, в частности, запись или чтение файла.



Рассмотрим небольшой пример применения. Допустим, нам надо создать программу для работы с базами данных. Поскольку создание подключения к базу данных и последующее его закрытие может быть затратно в плане производительности, и в то же время с одной базой данных могут одновременно работать несколько клиентов, то в этой ситуации мы как раз можем применить данный паттерн. Для начала создадим заголовочный файл **database.h** и определим в нем API:



```c

struct Database;        // условная база данных
struct Database* openDatabase(size_t id);   // открытие базы данных
void closeDatabase(struct Database* db);    // закрытие базы данных

void setUser(struct Database* db, size_t index, char* name);    // изменение данных
void printUsers(struct Database* db);   // получение данных
```



Здесь структура Database представляет условную базу данных - состояние модуля, которое зависит от клиента и которое может использоваться несколькими клиентами. Причем детали реализации этого состояния неизвестны, они скрыты от клиента, и клиент не знает, какие именно поля содержит структура Database.



Для работы с состоянием определены 4 функции. Функция openDatabase получает идентификатор базы данных (индекс в пуле подключений) и возращает объект Database, который затем используется клиентом. Для простоты здесь базы данных идентифицируются по числовым идентификатором, но в реальности можно было бы передавать и имя базы данных.



Функция closeDatabase получает объект Database и закрывает его. И также для непосредственной работы с базой данных определена функция setUser, которая получает объект базы данных, индекс (id) изменяемых данных и новое значение данных. И также определена функция printUsers, которая будет получать все данные и выводит их на консоль.



Далее создадим файл **database.c** и определим в нем реализацию API модуля:



```c

#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include "database.h" 
 
#define DATA_MAX_COUNT 5   // максимальное количество данных в условной базе данных
#define CON_MAX_COUNT 4 // максимальное количество подключений

// база данных - структура представляет разделяемое состояние
struct Database{
    size_t id;                     // индекс подключения
    char* data[DATA_MAX_COUNT];// условные данные
};
// подключение - структура для управления состоянием
struct Connection
{
  struct Database* db;  // подключение
  size_t count;            // количество обратившийся клиентов
};
// пул подключений
static struct Connection pool[CON_MAX_COUNT];

// открытие условной базы данных
struct Database* openDatabase(size_t id)
{
  // проверяем индекс базы данных
  assert(id<CON_MAX_COUNT && "Invalid database id");
  // если еще нет клиентов, которые обращаются к бд
  // значит база данных отсутствует, и ее надо создать
  if(pool[id].count==0) 
  {
    pool[id].db =  malloc(sizeof(struct Database)); // создаем базу данных
    pool[id].db->id = id;   // устанавливаем индекс подключения
  }
  pool[id].count++;     // увеличиваем счетчик клиентов
  return pool[id].db;   // возвращаем указатель на базу данных
}
// удаляем базу данных
void closeDatabase(struct Database* db)
{
  pool[db->id].count--;     // уменьшаем счетчик клиентов
  if(pool[db->id].count == 0)   // если клиентов больше нет
  {
    free(db);         // то освобождаем память
  }
}
// изменяем данные
void setUser(struct Database* db, size_t index, char* name)
{
    if(index < DATA_MAX_COUNT)
      db->data[index]=name;
    else
        printf("User not found\n");
}
// выводим данные на консоль
void printUsers(struct Database* db)
{
    for(size_t i =0; i < DATA_MAX_COUNT; i++)
    {   
        printf("%s\n",db->data[i]);
    }
}
```



Разделяемое состояние - структура Database состоит из числового идентификатора и массива data, который собственно представляет данные - некоторый набор строк.



Для управления состоянием определена дополнительная структура - Connection или условно подключение к базе данных, которая хранит указатель на объект Database и количество клиентов, которые в текущий момент работают с базой данных. И также для управления состоянием определен условный пул подключений - массив структур Connection.



Реализация функции openDatabase получает идентификатор базы данных, в качестве которого для простоты будет служить индекс соответствующего подключения в пуле подключений. Если база данных с переданным идентификатором еще не создана (то есть нет обращающихся к ней клиентов), то она создается. Иначе функция возвращает уже ранее созданный объект Database. И также увеличивается счетчик работающих в базой данных клиентов.



Функция closeDatabase уменьшает счетчик клиентов, и если клиентов больше нет, освобождает память объекта Database.



Функция setUser изменяет значение одного объекта в базе данных по индексу (Для простоты здесь просто присваиваем строку и не учитываем, что присваиваемая строка может быть выделена в динамической памяти)



Функция printUsers выводит все данные из базы данных на консоль.



Таким образом, грубо говоря, при первом обращении к базе данных создается подключение к базе данных, выделяется память. При последующих обращениях, чтобы из пула подключений используется уже ранее открытое подключение. Если все клиенты завершили работу, то закрываем подключение - освобождаем память.



В данном случае идентификаторы (названия баз данных) для простоты жестко привязаны к индексам структур Connection в массиве pool. Но при желании можно создавать структуры Database с независимыми идентификаторами с дополнительной логикой поиска подключений к определенным базам данных в пуле подключений.



Для тестирования модуля **database.c** определим следующий файл **app.c**:



```c

#include <stdio.h>
#include "database.h"

int main(void)
{
    // условный 1-й клиент создает базу данных с id 2
    struct Database* db1 = openDatabase(2); // 1-й клиент открывает базу данных
    // устанавливаем данные
    setUser(db1, 0, "Tom"); 
    setUser(db1, 1, "Bob");
    setUser(db1, 2, "Sam");
    printf("Users List for 1 client\n");
    printUsers(db1);

    // условный 2-й клиент создает базу данных с id 2
    struct Database* db2 = openDatabase(2);// 2-й клиент открывает базу данных
    setUser(db2, 3, "Alice");
    printf("\nUsers List for 2 client\n");
    printUsers(db2);
    
    closeDatabase(db1); // 1-й клиент закрывает базу данных
    closeDatabase(db2); // 2-й клиент закрывает базу данных
}
```



Здесь условно определены два клиента. Первый клиент работает с переменной db1, а второй клиент - с переменной db2. Каждый клиент сначала вызывает функцию openDatabase. Причем оба клиента обращаются к базе данных с одним и тем же идентификатором - 2. Однако в первом случае эта функция создаст новый объект Database, а во втором случае вернет уже существующий.



```c

struct Database* db1 = openDatabase(2); // 1-й клиент открывает бд - создается новая БД

// .......................

// условный 2-й клиент создает базу данных с id 2
struct Database* db2 = openDatabase(2);// 2-й клиент открывает бд - возвращается уже существующая БД
```



После того, как каждый клиент получил объект Database, идет некоторая работа. Первый клиент устанавливает первые три объекта в базе данных и выводит список объектов на консоль. Второй клиент устанавливает один объект в базе данных и также выводит список объектов на консоль. Но так как они работают с одной базой данных, то и список объектов для них будет одним и тем же.



После завершения работы клиенты должны закрыть базу данных с помощью функции closeDatabase:



```c

closeDatabase(db1); // 1-й клиент закрывает базу данных
closeDatabase(db2); // 2-й клиент закрывает базу данных - память освобождается
```



Но в первом случае функция closeDatabase просто уменьшает счетчик клиентов, а во втором освобождает память. После этого подключение закрыто.



Пример компиляции и работы программы:



```bash

c:\C>gcc -Wall -pedantic app.c database.c -o app & app
Users List for 1 client
Tom
Bob
Sam

Users List for 2 client
Tom
Bob
Sam
Alice

c:\C>
```

Иногда бывает необходимо предоставить клиенту интерфейс, реализация которого может отличаться и определяться после определения интерфейса в будущем, в том числе самим клиентом. То есть реализация интерфейса должна быть гибкой и при необходимости изменяться без изменения исходного кода. Распространенным решением в этом случае является применение паттерна **Стратегия** (некоторые также называют данный паттерн **динамический интерфейс** или **Dynamic Interface**)

Реализация паттерна состоит в определении на стороне модуля функции, которая принимает некоторый коллбек - указатель на другую функции. А внутри функции модуля вызываем через указатель этот колбек. В простейшем случае это выглядит следующим образом:

```c
/* API модуля */
typedef void (*action)();
void some_function(action callback);

/* реализация на стороне модуля */
void some_function(action callback)
{
    // вызывем колбек
    callback();
}

/* применение на стороне клиента */
// реализация коллбека
void printMessage()
{
    printf("Hello enoobis.ru\n");
}

int main(void)
{
    // вызываем API
    some_function(printMessage);
}
```

В API модуля помещаем определение функции some_function, которая принимает указатель на другую функцию. В реализации функции API в модуле вызываем переданную через указатель функцию. А на стороне клиента мы вызываем функцию API, передая ей через параметр указатель на другую функцию. Таким образом, конкретная реализация функции API зависит от передаваемого в нее коллбека и фактически может определяться в будущем и многократно изменяться.

Рассмотрим небольшую программку. Пусть в файле **sort.h** у нас определеен следующий интерфейс модуля:

```c
// тип указателя на функцию сравнения - принимает два параметра типа int и возвращает число int
typedef int (*comparator)(int x, int y);
// функция сортировки, принимает функцию  сравнения, массив и длину массива
void sort(comparator compare, int* array, size_t length);
```

API модуля состоит из одной функции sort, которая предназначена для сортировки массива чисел и которая принимает в качестве первого параметра функцию сравнения или функцию типа comparator. Этот тип определен строкой выше и представляет указатель на функцию, которая принимает два сравниваемых числа и возвращает число. Причем на момент определения файла мы не знаем, что это будет за функция. Мы только знаем, что она определяет логику сравнения двух чисел.

В файле **sort.c**, который представляет модуль функционала сортировки, определим реализацию функции sort:

```c
#include <stdio.h>
#include "sort.h"

// реализация функции сортировки
void sort(comparator compare, int* array, size_t length)
{
  for(size_t i=0; i<length-1; i++)
  {
    for(size_t j=i+1; j<length; j++)
    {
      // выполняем переданную функцию compare
      if(compare(array[i], array[j]))
      {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
      }
    }
  }
}
```

Здесь определена простейшая функция сортировки, которая сравнивает одно из чисел массива со всеми последующими и в зависимости от результата сравнения меняет сравниваемые числа местами. Причем результат сравнения определяет передаваемая в качестве первого параметра функция

```c
if(compare(array[i], array[j]))
{
    int temp = array[i];
    array[i] = array[j];
    array[j] = temp;
}
```

Если функция возвращает ненулевое значение (условно говоря истину), то первое число должно стоять после второго. И опять же подчеркиваю на момент определения данного кода мы не знаем, что это будет за функция compare.

Далее определим файл **app.c**, в котором используем функцию sort:

```c
#include <stdio.h>
#include "sort.h"

#define ARRAY_SIZE 4

// сортировка по возрастанию
int compareAsc(int x, int y)
{
  return x>y;
}
// сортировка по убыванию 
int compareDesc(int x, int y)
{
  return x<y;
}
int main(void)
{
    // массив для сортировки
    int array[ARRAY_SIZE] = {3, 5, 6, 1};
    // сортируем массив по возрастанию
    sort(compareAsc, array, ARRAY_SIZE);

    printf("Ascending: ");

    for(size_t i=0; i<ARRAY_SIZE; i++)
    {
        printf("%d ", array[i]);
    }

    // сортируем массив по убыванию
    sort(compareDesc, array, ARRAY_SIZE);

    printf("\n\nDescending: ");

    for(size_t i=0; i<ARRAY_SIZE; i++)
    {
        printf("%d ", array[i]);
    }
}
```

Здесь определены две функции сравнения, которые соответствуют определению указателя на функцию comparator. Функция compareAsc возвращает 1, если первое число больше второго. То есть первое число (большее число) должно располагаться после второго. Таким образом, речь идет о сортировке по возрастанию. Другая функция - compareDesc возвращает 1, если первое число меньше второго. То есть первое число (меньшее число) должно располагаться после второго. Соответственно речь идет о сортировке по убыванию.

В функции main вызываем функцию sort и передаем в нее одну из этих двух функций сравнения. И таким образом, мы можем динамически изменить поведение функции (в данном случае механизм сортировки). Пример компиляции и работы программы:

```bash
c:\C>gcc -Wall -pedantic app.c sort.c -o app & app
Ascending: 1 3 5 6

Descending: 6 5 3 1
c:\C>
```

Если проект содержит множество файлов, то может возникнуть ситуация, что один и тот же заголовочный файл будет подключен несколько раз. Однако на этапе компиляции это может привести к ошибкам. Например, пусть у нас есть заголовочный файл **user.h** со следующим кодом:

```c
struct User
{
  char* name;
  unsigned age;
};

void printUser(struct User);
```

Здесь определена структура User и прототип функции printUser, которая должна выводить структуру User на консоль.

И также пусть будет файл **user.c** с определением функции printUser:

```c
#include <stdio.h>
#include "user.h"

void printUser(struct User user)
{
    printf("Name: %s  Age: %d\n", user.name, user.age);
}
```

Также пусть у нас будет заголовочный файл **userlist.h** со следующим кодом:

```c
#include <stdio.h>
// подключаем заголовочный файл, где определена структура User
#include "user.h"  
// функция вывода массива структур User
void printUserList(struct User*, size_t);
```

Здесь вначале подключается заголовочный файл "user.h", поскольку нам предстоит работать со структурами User, а потом определяется прототип функции printUserList для вывода массива структур User определенной длины на консоль.

В файле **userlist.c** реализуем функцию printUserList:

```c
#include <stdio.h>
#include "userlist.h"

void printUserList(struct User* users, size_t count)
{
    for(size_t i=0; i < count; i++)
    {
        printUser(users[i]);
    }
}
```

Данная реализация функции проходит по массиву users и для каждого его элемента вызывает функцию printUser, которая объявлена в подключенном файле "user.h".

И определим файл **app.c**, который будет представлять главный файл программы и будет использовать функцию printUserList для вывода массива структур User на консоль:

```c
#include "userlist.h"   // подключаем API модуля userlist
#include "user.h"       // подключаем API модуля user

#define USERS_COUNT 4

int main(void)
{
    struct User users[USERS_COUNT] = 
    {
        {"Tom", 39}, {"Bob", 42},
        {"Sam", 29}, {"Alice", 34}
    };
    printUserList(users, USERS_COUNT);
}
```

Таким образом, у нас определено 5 файлов:

- user.h

- user.c

- userlist.h

- userlist.c

- app.c

Хотя у нас казалось бы довольно простая программа, где сложно допустить ошибку, но тем не менее на стадии компиляции мы получим ошибку

```bash
c:\C>gcc -Wall -pedantic app.c userlist.c user.c -o app & app
In file included from app.c:3:
user.h:1:8: error: redefinition of 'struct User'
    1 | struct User
      |        ^~~~
In file included from userlist.h:1,
                 from app.c:2:
user.h:1:8: note: originally defined here
    1 | struct User
      |        ^~~~
user.h:7:6: error: conflicting types for 'printUser'; have 'void(struct User)'
    7 | void printUser(struct User);
      |      ^~~~~~~~~
user.h:7:6: note: previous declaration of 'printUser' with type 'void(struct User)'
    7 | void printUser(struct User);
```

Так по консольному выводу мы видим, что идет переопределение структуры User, кроме того, проблемы с функцией printUser.

И проблема в нашем случае состоит в том, что в файле **app.c** два раза подключается заголовочный файл **user.h**

```c
#include "userlist.h"   // подключаем API модуля userlist
#include "user.h"       // подключаем API модуля user
```

Ведь в файле **userlist.h** уже подключен файл "user.h". Поэтому заголовочные файлы следует подключать в программу только один раз. И чтобы выйти из этой ситуации, мы можем убрать подключение файла **user.h**:

```c
#include "userlist.h"   // подключаем API модулей userlist и user

#define USERS_COUNT 4

int main(void)
{
    struct User users[USERS_COUNT] = 
    {
        {"Tom", 39}, {"Bob", 42},
        {"Sam", 29}, {"Alice", 34}
    };
    printUserList(users, USERS_COUNT);
}
```

Теперь ошибки не будет. Однако в большой кодовой базе, где подключается куча заголовочных файлов бывает сложно уследить за всеми подключениями. И в этом случае для проверки подключения используют два способа: выражение **#ifdef** и директиву **#pragma once**

Использование директивы `#pragma once` может показаться наиболее простым способом, однако это выражение не определено в стандарте языка С, хотя и поддерживается многими препроцессорами языка С. Эта директива указывается в подключаемом заголовочном файле:

```c
#pragma once    // однократное подключение файла

struct User
{
  char* name;
  unsigned age;
};

void printUser(struct User);
```

Минусом данного подхода является то, что можно наткнуться на компилятор, препроцессор которого не поддерживает данную директиву.

Другой подход представляет проверка определения константы с помощью директивы **#ifndef** в следующем виде:

```c
#ifndef SOMECODE_H  // если НЕ определена константа SOMECODE_H
#define SOMECODE_H  // определяем константу SOMECODE_H

 // здесь идет определение заголовочного файла

#endif              // завершение конструкции #ifndef
```

Сначала мы проверяем, что НЕ определена некоторая константа. Если она НЕ определена, то это значит, что заголовочный файл НЕ подключен.

Если константа НЕ определена, определяем ее с помощью директивы **#define** и далее вплоть до выражения **#ifdef** помещаем содержимое заголовочного файла - определение структур, констант и прототипов функций.

Название проверяемой константы должно быть уникально на всем множестве файлов проекта. Поэтому обычно в качестве названия константы используется название подключаемого файла, где точка заменяется прочерком. Например, для файла **user.h** определяется константа **user_h** или **USER_H**. Бывают ситуации, особенно при подключении внешних заголовочных файлов, созданных другими разработчиками, что названия этих файлов дублируются. В этом случае можно в качестве названия констант можно генерировать уникальные значения UUID или использовать числовые метки времени.

Применение **#ifndef** в файле **user.h**:

```c
#ifndef user_h  // если user_h не определена
#define user_h  // определяем user_h 

struct User     // и помещаем определение структуры User
{
  char* name;
  unsigned age;
};

void printUser(struct User);  // и определение прототипа функиции

#endif    // конец конструкции ifndef
```

После этого мы можем многократно включать заголовочный файл в других файлах кода:

```c
#include "userlist.h"   // подключаем API модуля userlist
#include "user.h"       // подключаем API модуля user
#include "user.h"       // подключаем API модуля user
#include "user.h"       // подключаем API модуля user

#define USERS_COUNT 4

int main(void)
{
    struct User users[USERS_COUNT] = 
    {
        {"Tom", 39}, {"Bob", 42},
        {"Sam", 29}, {"Alice", 34}
    };
    printUserList(users, USERS_COUNT);
}
```

Однако поскольку идет проверка на определение константы user_h, то содержимое заголовочного файла будет вставляться только один раз.

Итерация или перебор некоторого набора объектов является довольно частой задачей при работе с наборами данных. Если набор данных представляет структуру данных с произвольным доступом, например, массив, то мы можем использовать индексы для получения конкретных элементов набора. Проблема может возникнуть, когда мы захотим изменить структуру данных. Например, мы хранили строки, а потом решили, что каждый элемент будет представляеть структуру и будет хранить две строки. Если внешний код использовал этот набор, то изменение структуры данных потребует изменения внешнего кода, который обращается к этим данным.

Другая проблема можем заключаться в нежелательном доступе к данным. Например, какждый элемент в массиве представляет структуру с кучей полей. Но мы хотим, чтобы внешний код имел доступ только к некоторым из этих полей, и чтобы реализация структуры данных была скрыта от внешнего кода. Но при этом необходимо, что внешний код имел удобный доступ к данным. К тому же внешнему коду может быть интересная только какие-то конкретные поля структуры, а не вся структура в целом. Поэтому возвращение всей структуры, которая представляет данные, будет избыточно.

При работе со структурами данных с произвольным доступом типовым решением является определение функции, которая принимает индекс объекта в наборе и возвращает данные объекта. В общем случае это выглядит так:

```c
/* API модуля - функция принимает индекс элемента и возвращает некоторые данные */
int getX(int index);


/* Реализация API модуля */
#define MAX_ELEMENTS 4
// структура, которая представляет данные
struct Data
{
    int x;
    int y;
};
// сами данные
static struct Data elements[MAX_ELEMENTS]={{1,2},{3,4},{5,6},{7,8}};
// функция для доступа к данным по индексу
int getX(int index)
{
  return elements[index].x;
}


/* Код клиента, который использует API */
int x1 = getX(1);
int x2 = getX(2);
```

Благодаря функции-абстракции над обращением к элементу по индексу мы можем предоставить клиенту только те данные, которые ему нужны и к которым он может иметь доступ. А если в будущем структура данных измениться, на стороне клиента код не изменится. Данный паттерн еще называют **External Iterator** или внешний итератор.

Рассмотрим небольшой пример. Пусть в заголовочном файле **account.h** у нас определен следующий API:

```c
#define ACCOUNT_NUMBER 200
char* getUserName(size_t index);
```

Константа ACCOUNT_NUMBER представляет максимальное количество данных - учетных данных пользователей, а функция getUserName возвращает имя пользователя по определенному индексу.

В файле **account.c** определим реализацию API:

```c
#include <stdio.h>
#include "account.h"

#define NAME_SIZE 20
#define PASSWORD_SIZE 20
// структура данных
struct ACCOUNT
{
  char login[NAME_SIZE];
  char password[PASSWORD_SIZE];
};
// типовые данные
static struct ACCOUNT accounts[ACCOUNT_NUMBER] = 
{
  {"Tom", "qwerty"}, {"Bob", "123456"}, 
  {"Sam", "6589967"}, {"Tim", "eruiyiu"}
};

// возвращаем логин
char* getUserName(size_t index)
{
  return accounts[index].login;
}
```

Здесь данные представлены структурой Account, которая хранит условно имя пользователя/логин и его пароль. И также определен типовой набор данных - массив accounts. Пароль в этой структуре может представлять такие данные, которые не должны быть видны извне, поэтому определяем функционал только для возвращения логина с помщью функции getUserName, которая получает индекс пользователя в массиве accounts.

Определим основной файл программы - **app.c**, в котором будем обращаться к данным:

```c
#include <stdio.h>
#include "account.h"

int main(void)
{
  for(size_t i=0; i < ACCOUNT_NUMBER; i++)
  {
    char* username = getUserName(i);
    if(username[0] == 'T')
    {
      printf("%s\n", username);
    }
  }
}
```

Здесь проходим по всем элементам и получаем имя каждого пользователя с помощью функции getUserName. Для примера выводим на консоль все имена пользователей, которые начинаются на "T".

Данный паттерн позволяет абстрагироваться от строения структуры данных и обеспечить некоторую безопасность от несанкционированного доступа. Однако минусом подхода - он не очень удобен при работе с последовательными структурами данных типа связанных списков, где может потребоваться динамическое добавление или удаление элементов.

Нередко данные представляют последовательные структуры, например, связанные списки, хеш-таблицы, деревья, очереди, стеки и т.д. При переборе объектов подобных структур может быть нежелательным предоставление прямого доступа к данным внешнему кода, например, если мы хотим скрыть извне какие-то критичные данные. Кроме того, структура данных может в будущем может измениться, что потребует изменить внешний код, который использует изменившуюся структуру данных. И для решения этих проблем для перебора данных определяют специальную абстракцию - **итераторы**.

Внешний код создает объект итератора, который указывает на определенный элемент в наборе данных (обычно на первый элемент, но необязательно). Функция итератора принимает объект итератора извлекает элемент, на который указывает итератор, и перемещает итератор на следующий элемент в наборе. Таким образом, при последовательном многократном вызове функции итератора мы можем перебрать все объекты в наборе.

В общем случае итератор требует наличие как минимум трех функций

```c
// создание итератора
ITERATOR* createIterator();

// Получаем текущий элемент итератора и сдвигаем итератор на следующий элемент
// Если элементов в наборе больше нет, то возвращается NULL
void* getNext(ITERATOR* iterator);

// Удаляем итератор
void destroyIterator(ITERATOR* iterator);
```

Внешний код создает итератор, вызывает функцию итератора для последовательного получения элементов и после окончания работы удаляет итератор:

```c
void* element;
ITERATOR* it = createIterator(); // создаем итератор

while(element = getNext(it))    // в цикле получаем текущий элемент итератора
{
  // некоторые действия с итератором
}

destroyIterator(it);    // удаляем итератор
```

В данном случае мы опять же можем не возвращать весь элемент из набора данных, а лишь те его компоненты, к которым внешний код может иметь доступ. И даже если в будущем структура данных изменится, например, со связного списка на массив или наоборот, то итератор скроет все эти изменения от внешнего кода. Мы лишь изменяем код итератора для получения элемента набора. Внешний же код, который использует итератор, остается прежним.

Подобный паттерн используется в частности при работе с файлами. Так, встроенная библиотечная функция `getline()` проходит по всем строкам в файле и сдвигает позицию итератора в указателе `FILE`.

Рассмотрим следующую задачу. Сначала определим в файле **account.h** следующий API:

```c
// создание итератора
struct ITERATOR* createIterator(void);

// Получаем данные
char* getUserName(struct ITERATOR*);

// Удаляем итератор
void destroyIterator(struct ITERATOR*);

// создание списка
void createAccountList(void);
// удаление списка
void deleteAccountList(void);
```

Функция createIterator создает итератор, который будет представлять структуру ITERATOR, и возвращает указатель на него. Функция destroyIterator удаляет итератор и освобождает его память. Для получения данных из итератора API предоставляет функцию getUserName, которая будет возвращать строку. Чтобы иметь некоторые для работы также определена функция createAccountList, которая создает список, а для удаления данных - функция deleteAccountList.

В файле **account.c** определим реализацию итератора:

```c
#include <stdio.h>
#include <stdlib.h>
#include "account.h"

// структура данных
struct ACCOUNT
{
  char* login;
  char* password;
  struct ACCOUNT* next;
};
// структура итератора
struct ITERATOR
{
  char* data;
  struct ACCOUNT* element;
};
// список объектов - указатель на первый элемент
static struct ACCOUNT* accountList;

struct ITERATOR* createIterator()
{
  struct ITERATOR* iterator = malloc(sizeof(struct ITERATOR));
  iterator->element = accountList;
  return iterator;
}
void destroyIterator(struct ITERATOR* iterator)
{
  free(iterator);
}

char* getUserName(struct ITERATOR* iterator)
{
  if(iterator->element)
  {
    iterator->data=iterator->element->login;       // устанавливем данные итератора
    iterator->element = iterator->element->next;   // сдвигаем итератор на следующий элемент списка
    return iterator->data;
  }
  return NULL;
}

// создаем список с начальными данными
void createAccountList()
{
  struct ACCOUNT* tom = malloc(sizeof(struct ACCOUNT));
  tom->login ="Tomas";
  tom->password = "qwerty";
  accountList = tom;

  struct ACCOUNT* bob = malloc(sizeof(struct ACCOUNT));
  bob->login ="Bob";
  bob->password = "12345";
  tom->next = bob;

  struct ACCOUNT* tim = malloc(sizeof(struct ACCOUNT));
  tim->login ="Tim";
  tim->password = "45678";
  bob->next = tim;
  tim->next = 0;
}

// создаем список с начальными данными
void deleteAccountList()
{
  while(accountList)
  {
    free(accountList);
    accountList = accountList->next;
  }
}
```

Здесь сами данные представлены структурой ACCOUNT. Допустим, она представляет учетную запись и хранит имя и пароль пользователя. И поскольку эта структура также представляет элемент связанного списка учетных записей, то она также определяет поле next, которое ссылается на следующую структуру ACCOUNT:

```c
struct ACCOUNT
{
  char* login;
  char* password;
  struct ACCOUNT* next;
};
```

Для перебора списка структур ACCOUNT определена структура ITERATOR

```c
struct ITERATOR
{
  char* data;
  struct ACCOUNT* element;
};
```

В поле data структура будет хранить собственно данные, которые будут возвращаться пользователю. В нашем случае данные ACCOUNT состоят из двух частей - имени и пароля. Однако, допустим, мы не хотим, чтобы к паролю был доступ, поэтому будем возвращать только имя пользователя через данное поле data.

Другое поле - element представляет текущий элемент в наборе объектов ACCOUNT, на который указывает итератор.

После определения структур определяем указатель на структуру ACCOUNT, который будет представлять первый элемент списка (и по сути весь список по цепочке):

```c
static struct ACCOUNT* accountList;
```

Далее идет определение функции создания итератора:

```c
struct ITERATOR* createIterator()
{
  struct ITERATOR* iterator = malloc(sizeof(struct ITERATOR));
  iterator->element = accountList;
  return iterator;
}
```

Здесь выделяется память под структуру ITERATOR и устанавливается текущий элемент - первый элемент списка.

Также определена функция удаления итератора, которая просто освобождает его память:

```c
void destroyIterator(struct ITERATOR* iterator)
{
  free(iterator);
}
```

Для перемещения итератора по списку определена функция getUserName:

```c
char* getUserName(struct ITERATOR* iterator)
{
  if(iterator->element)
  {
    iterator->data=iterator->element->login;       // устанавливем данные итератора
    iterator->element = iterator->element->next;   // сдвигаем итератор на следующий элемент списка
    return iterator->data;
  }
  return NULL;
}
```

В данном случае если текущий элемент интератора не равен NULL (если он равен NULL, то это символизирует конец списка), то в поле data итератора получаем логин пользователя - это те данные, которые возвращаются из функции. И затем сдвигаем итератор на следующий элемент списка.

Таким образом, при вызове функции getUserName внешний код получит логин из текущей учетной записи, а итератор сдвигается к следующей учетной записи в списке.

Для тестирования итератора в основной файле программы - файле **app.c** определим следующий код:

```c
#include <stdio.h>
#include "account.h"

int main(void)
{
    createAccountList();  // создаем данные
    char* username;
    struct ITERATOR* iterator = createIterator(); // создаем итератор
    while((username = getUserName(iterator)))   // проходим итератором по списку учетных записей
    {
        printf("%s\n", username);
    }
    destroyIterator(iterator);  // удаляем итератор
    deleteAccountList();  // удаляем данные
}
```

Вначале создаем список, чтобы у нас были типовые данные для теста, и итератор. Затем в цикле последовательно проходим итератором по всем элементам:

```c
while((username = getUserName(iterator)))
```

При каждом вызове функции `getUserName()` мы получим значение поля login текущего элемента, на который указывает итератор, и переместим итератор к следующему элементу.

Пример компиляции и работы программы:

```bash
c:\C>gcc -Wall -pedantic app.c account.c -o app & app
Tomas
Bob
Tim

c:\C>
```

Стоит отметить, что конкретная реализация итератора может отличаться в зависимости от требований и конкретных задач. Так, в примере выше итератор хранит данные в отдельном поле, но мы можем обойтись и без него и напрямую возвращать данные. Также мы можем возвращать указатель на данные или их копию. Но общая схема будет аналогичной - вызываем функцию, которую передаем итератор, и итератор возвращает данные и переходит к новому элементу.

При такой организации программы мы можем при необходимости обновлять структуру данных, внося некоторые изменения в код итератора, но эти обновления не затронут внешний код - он также будет вызвывать функцию, в которую будет передавать итератор. Использование итератора скорет от внешнего кода всю сложность реализации перебора объектов. Кроме того, внешнему коду доступны только к те данные, к которым он может имет доступ.

В то же время использование итератора усложняет общую организацию программы. Внешний код должен не забывать вызывать функции создания и удаления итератора.

Итератор-коллбек представляет альтернативу стандартному итератору, который описывался в прошлой теме, он также позволяет перебирать элементы структуры данных с последовательным доступом и также позволяет скрыть от внешнего кода детали реализации прохода по элементам набора и логику возвращения данных.

Рассмотрим суть итератора-коллбека. В API определяется указатель на функцию, которая в качестве параметра принимает перебираемый элемент из набора данных:

```c
/* API  итератора */
// указатель на функцию, которая получает перебираемый элемент
typedef void (*CALLBACK)(void* element);

// Функция перебора объектов, которая вызывает коллбек-callback
void iterate(CALLBACK callback);
```

И также определяется функция перебора, которая принимает в качестве параметра вышеопределенный указатель на функцию, то есть коллбек. При необходимости обе функции могут принимать дополнительные параметры.

Клиент - внешний код определяет функцию-коллбек и передает ее в вызов функции перебора:

```c
/* Код клиента */

// функция-коллбек, которая принимает перебираемый элемент
void some_action(void* element)
{
  // Операции над элементом
}

int main(void)
{
    // вызываем функцию перебора и передаем в нее коллбек
    iterate(some_action);
}
```

Таким образом, реализация итератора также скрывается от внешнего кода. Благодаря чему мы можем в будущем изменить структуру данных, изменить реализацию функции перебора, но код клиента не изменится - он также будет использовать функцию перебора и передавать в нее функцию-коллбек. Кроме того, от внешнего кода скрыто строение структуры данных, клиент получает только те данные, которые мы ему предоставим и избегаем нежелательнного доступа к данным. При этом для клиента упрощается работа - в отличие от использования стандартного итератора клиент не должен вызывать функции создания и удаления итератора.

Рассмотрим небольшой пример. Пусть в заголовочном файле **account.h** будет определен API итератора:

```c
// указатель на функцию, которая получает перебираемый элемент
typedef void (*CALLBACK)(char* username);

// Функция перебора объектов, которая вызывает коллбек-callback
void iterateUserNames(CALLBACK callback);

// создание списка
void createAccountList(void);
// удаление списка
void deleteAccountList(void);
```

Здесь определена указатель на функцию-коллбек, которая имеет тип **void** и в качестве параметра принимает строку - указатель char*. И также определена функция перебора interateUserNames, которая принимает функцию-коллбек.

Чтобы у нас был некоторый набор данных для теста также объявлена функци создания списка createAccountList, а для удаления списка - функция deleteAccountList.

В файле **account.c** определим реализацию перебора списка:

```c
#include <stdio.h>
#include <stdlib.h>
#include "account.h"

// структура данных
struct ACCOUNT
{
  char* username;
  char* password;
  struct ACCOUNT* next;
};
// список объектов - указатель на первый элемент
static struct ACCOUNT* accountList;

// перебираем элементы списка
void iterateUserNames(CALLBACK callback)
{
    struct ACCOUNT* current = accountList;  // текущий перебираемый элемент списка
    while(current)  // пока элемент не будет равен NULL
    {
      callback(current->username);  // вызываем коллбек
      current = current->next;  // получаем следующий элемент списка
    }
}

// создаем список с начальными данными
void createAccountList()
{
  struct ACCOUNT* tom = malloc(sizeof(struct ACCOUNT));
  tom->username ="Tomas";
  tom->password = "qwerty";
  accountList = tom;

  struct ACCOUNT* bob = malloc(sizeof(struct ACCOUNT));
  bob->username ="Bob";
  bob->password = "12345";
  tom->next = bob;

  struct ACCOUNT* tim = malloc(sizeof(struct ACCOUNT));
  tim->username ="Tim";
  tim->password = "45678";
  bob->next = tim;
  tim->next = 0;
}

// создаем список с начальными данными
void deleteAccountList()
{
  while(accountList)
  {
    free(accountList);
    accountList = accountList->next;
  }
}
```

Здесь сами данные представлены структурой ACCOUNT, которая хранит имя и пароль пользователя. Кроме того, с поля свойства next она указывает на следующий элемент списка. Также определен указатель этой структуры accountList, который представляет первый элемент и по цепочке весь список.

Вспомогательные функции createAccountList и deleteAccountList создают и удаляют список объектов ACCOUNT. А основная работа итератора происходит в функции iterateUserNames, которая в качестве параметра принимает функцию-коллбек. Допустим, пароль пользователя представляет чувствительные данные, к которым внешний код не должен иметь доступ. Поэтому при переборе будет отдавать клиенту только имя пользователя. Для перебора просто проходит по цепочке по всем элементам списка, начиная с первого элемента accountList, пока не дойдем до NULL, что будет символизировать конец списка:

```c
void iterateUserNames(CALLBACK callback)
{
    struct ACCOUNT* current = accountList;  // текущий перебираемый элемент списка
    while(current)  // пока элемент не будет равен NULL
    {
      callback(current->username);  // вызываем коллбек
      current = current->next;  // получаем следующий элемент списка
    }
}
```

В цикле получаем поле username из каждой структуры ACCOUNT и передаем его в функцию-коллбек. Что в этой функции будет происходить, мы не знаем.

Для тестирования итератора определим следующий файл **app.c**:

```c
#include <stdio.h>
#include "account.h"

void printUserName(char* username)
{
    printf("%s\n", username);
}
void printNameT(char* username)
{
    if(username[0]=='T')  // если слово начинается на букву T
        printf("%s\n", username);
}

int main(void)
{
    createAccountList();  // создаем данные

    iterateUserNames(printUserName);    // выводим все имена пользователей

    printf("\n"); // для разделения вывода

    iterateUserNames(printNameT);   // выводим только те имена, которые начинаются на Т

    deleteAccountList();  // удаляем данные
}
```

Для тестирования здесь определены две функции-коллбека, которые по возвращаемому типу и параметрам соответствуют определению указателя CALLBACK из API. Так, функция printUserName принимает строку и выводит ее на консоль. Другая функция - printNameT также выводит строку на консоль, но только если строка начинается на букву T.

Затем вызываем функцию перебора interateUserNames и передаем в нее определенный коллбек:

```c
iterateUserNames(printUserName);

iterateUserNames(printNameT);
```

Пример компиляции и работы программы:

```bash
c:\C>gcc -Wall -pedantic app.c account.c -o app & app
Tomas
Bob
Tim

Tomas
Tim

c:\C>
```

Программа на языке Си может компилироваться для различных платформ с учетом различного набора конфигурационных настроек. Мы можем одну и ту же программу компилировать под разные операционные системы. Встроенная библиотека языка Си поддерживает только общий функционал, который может работать на всех системах, но которого может оказаться недостаточно. Но кроме того, каждая операционная система может определять свои специфичные функции, и, возможно, мы захотим использовать эти функции, которые специфичны для каждой платформы.

Кроме того, возможно, мы захотим, чтобы при одних конфигурационных настройках применялись одни функции, при других же настройках - другие функции. Это ставит нас перед проблемой вариативности программы - программа определяет различные варианты, которые будут компилироваться при определенном наборе настроек. Например, если программа компилируется под Linux, вызываем и используем одни функции, если же под Windows - используем другие функции. В общем случае для управления вариантами компиляции применяется препроцессорная директива **#ifdef**.

Допустим, мы хотим реализовать запись некоторого текста в файл, который будет храниться во вновь созданном каталоге. Но этот каталог в зависимости от флага конфигурации, создается либо в текущей папке, либо в системной папке пользователя (папка, которая называется по имени пользователя). Кроме того, программа должна работать как на Windows, так и на Linux.

Наиболее очевидная и в некотором смысле наивная попытка решить эту задачу представляет определение единого файла программы, который содержит множество директив **#ifdef** и тем самым позволяет разграничить варианты кода, наподобие следующего:

```c
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#ifdef __unix__
  #include <sys/stat.h>
  #include <fcntl.h>
  #include <unistd.h>
#elif defined _WIN32
  #include <windows.h>
#endif

int main(void)
{
  char dirname[60];         // пусть к папке
  char filename[60];        // пусть к файлу
  char* text = "Hello enoobis.ru";      // некоторый текст для сохранения
  #ifdef __unix__           // если Linux
    #ifdef HOME_DIR         // если сохраняем в домашнем каталоге пользователя
      sprintf(dirname, "%s%s", getenv("HOME"), "/newdir/");
      sprintf(filename, "%s%s", dirname, "newfile");
    #elif defined CURRENT_DIR       // если сохраняем текущем каталоге
      strcpy(dirname, "newdir");
      strcpy(filename, "newdir/newfile");
    #endif
    mkdir(dirname,S_IRWXU);
  #elif defined _WIN32      // если Windows
    #ifdef HOME_DIR         // если сохраняем в домашнем каталоге пользователя
      sprintf(dirname, "%s%s%s", getenv("HOMEDRIVE"), getenv("HOMEPATH"), "\newdir\");
      sprintf(filename, "%s%s", dirname, "newfile");
    #elif defined CURRENT_DIR              // если сохраняем текущем каталоге
      strcpy(dirname, "newdir");
      strcpy(filename, "newdir\newfile");
    #endif
    CreateDirectory (dirname, NULL);
  #endif
  // запись файла
  FILE* f = fopen(filename, "w+");
  fwrite(text, 1, strlen(text), f);
  fclose(f);

  return 0;
}
```

Здесь мы проверяем установку двух констант. Если установлена константа `__unix__`, то мы имеем дело с Linux, если же установлена константа `_WIN32`, то программа компилируется для Windows. В зависимости от установки констант, подключаем те или иные заголовочные файлы:

```c
#ifdef __unix__
  #include <sys/stat.h>
  #include <fcntl.h>
  #include <unistd.h>
#elif defined _WIN32
  #include <windows.h>
#endif
```

Затем в зависимости от системы в функции main выполняем создание каталога и запись в него файла:

```c
#ifdef __unix__           // если Linux
    #ifdef HOME_DIR         // если сохраняем в домашнем каталоге пользователя
      sprintf(dirname, "%s%s", getenv("HOME"), "/newdir/");
      sprintf(filename, "%s%s", dirname, "newfile");
    #elif defined CURRENT_DIR       // если сохраняем текущем каталоге
      strcpy(dirname, "newdir");
      strcpy(filename, "newdir/newfile");
    #endif
    mkdir(dirname,S_IRWXU);
  #elif defined _WIN32      // если Windows
    #ifdef HOME_DIR         // если сохраняем в домашнем каталоге пользователя
      sprintf(dirname, "%s%s%s", getenv("HOMEDRIVE"), getenv("HOMEPATH"), "\newdir\");
      sprintf(filename, "%s%s", dirname, "newfile");
    #elif defined CURRENT_DIR              // если сохраняем текущем каталоге
      strcpy(dirname, "newdir");
      strcpy(filename, "newdir\newfile");
    #endif
    CreateDirectory (dirname, NULL);
  #endif
```

Если установлена константа **HOME_DIR** каталог создается в домашней папке пользователя, а если установлена константа `CURRENT_DIR` - в текущей папке программы.

То есть фактически здесь определены две разные реализации для конкретной операционной системы, помещенные в один файл. Однако в таком коде трудно ориентироваться. Платформо-зависимый и платформо-независимый код смешены в одной функции. А что, если добавить еще одно выражение `#ifdef` для еще одной операционной системы? Поддерживаемость и читабельность кода будет стремиться к нулю. Посмотрим, как исправить эту ситуацию.

### Выделение вариантов кода в отдельную функцию

Самое простое решение состоит в вынесении кода, который работает с вариантами, в отдельные функции. Затем эти функции вызываются из основной части программы, которая будет содержать только независимый от платформы код:

```c
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#ifdef __unix__
  #include <sys/stat.h>
  #include <fcntl.h>
  #include <unistd.h>
#elif defined _WIN32
  #include <windows.h>
#endif

void getDirectoryName(char* dirname)
{
  #ifdef __unix__
    #ifdef HOME_DIR
      sprintf(dirname, "%s%s", getenv("HOME"), "/newdir/");
    #elif defined CURRENT_DIR
      strcpy(dirname, "newdir/");
    #endif
  #elif defined _WIN32
    #ifdef HOME_DIR
      sprintf(dirname, "%s%s%s", getenv("HOMEDRIVE"), getenv("HOMEPATH"), "\newdir\");
    #elif defined CURRENT_DIR
      strcpy(dirname, "newdir\");
    #endif
  #endif
}

void createNewDirectory(char* dirname)
{
  #ifdef __unix__
    mkdir(dirname,S_IRWXU);
  #elif defined _WIN32
    CreateDirectory (dirname, NULL);
  #endif
}

int main(void)
{
  char dirname[60];
  char filename[60];
  char* text = "Hello enoobis.ru";
  getDirectoryName(dirname);
  createNewDirectory(dirname);
  sprintf(filename, "%s%s", dirname, "newfile");
  FILE* f = fopen(filename, "w+");
  fwrite(text, 1, strlen(text), f);
  fclose(f);
  return 0;
}
```

Теперь платформо-зависимый код выделен в две функции - getDirectoryName (для получения пути к папке) и createNewDirectory (для создания новой папки). В таком коде гораздо проще ориентироваться.

Тем не менее здесь сохраняется другая проблема - дублирование кода - мы дублируем проверку констант `__unix__` и `_WIN32`, чтобы определить текущую систему. И также дублируем проверку констант **HOME_DIR** и `CURRENT_DIR`, чтобы определить каталог. А если мы захотим добавить поддержку еще одной платформы, то нам придется менять код в нескольких местах.

### Определение примитивов для работы с вариантами

Частичное решение проблемы дублирования кода проверки условий компиляции в общем случае заключается в вынесении работы с отдельными вариантами в отдельные примитивы - функции:

```c
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#ifdef __unix__
  #include <sys/stat.h>
  #include <fcntl.h>
  #include <unistd.h>
#elif defined _WIN32
  #include <windows.h>
#endif


void getHomeDirectory(char* dirname)
{
  #ifdef __unix__
    sprintf(dirname, "%s%s", getenv("HOME"), "/newdir/");
  #elif defined _WIN32
    sprintf(dirname, "%s%s%s", getenv("HOMEDRIVE"), getenv("HOMEPATH"), "\newdir\");
  #endif
}

void getCurrentDirectory(char* dirname)
{
  #ifdef __unix__
    strcpy(dirname, "newdir/");
  #elif defined _WIN32
    strcpy(dirname, "newdir\");
  #endif
}

void getDirectoryName(char* dirname)
{
  #ifdef HOME_DIR
    getHomeDirectory(dirname);
  #elif defined CURRENT_DIR
    getCurrentDirectory(dirname);
  #endif
}

void createNewDirectory(char* dirname)
{
  #ifdef __unix__
    mkdir(dirname,S_IRWXU);
  #elif defined _WIN32
    CreateDirectory (dirname, NULL);
  #endif
}

int main(void)
{
  char dirname[60];
  char filename[60];
  char* text = "Hello enoobis.ru";
  getDirectoryName(dirname);
  createNewDirectory(dirname);
  sprintf(filename, "%s%s", dirname, "newfile");
  FILE* f = fopen(filename, "w+");
  fwrite(text, 1, strlen(text), f);
  fclose(f);
  return 0;
}
```

Теперь получание пути к папке разбита на две функции - два варианта - для домашней папки пользователя и для текущей папки:

```c
void getHomeDirectory(char* dirname)
{
  #ifdef __unix__
    sprintf(dirname, "%s%s", getenv("HOME"), "/newdir/");
  #elif defined _WIN32
    sprintf(dirname, "%s%s%s", getenv("HOMEDRIVE"), getenv("HOMEPATH"), "\newdir\");
  #endif
}

void getCurrentDirectory(char* dirname)
{
  #ifdef __unix__
    strcpy(dirname, "newdir/");
  #elif defined _WIN32
    strcpy(dirname, "newdir\");
  #endif
}
```

Затем в функции getDirectoryName в зависимости от установки констант вызываем ту или иную функцию:

```c
void getDirectoryName(char* dirname)
{
  #ifdef HOME_DIR
    getHomeDirectory(dirname);
  #elif defined CURRENT_DIR
    getCurrentDirectory(dirname);
  #endif
}
```

Это позволило избавиться от проверки одной категории вариантов - HOME_DIR/CURRENT_DIR, однако дублирование проверки на операционную систему сохраняется. Кроме того, вынесение вариантов в отдельные функции несколько увеличивает сложность программы, код становится длинее, что опять же может осложнить его поддержку. В следующей статье посмотрим, как мы можем решить эту проблему.

В прошлой теме мы рассмотрели проблему вариантов программы, когда в зависимости от внешних условий/констант программа использует при компиляции тот или иной код. Возьмем код программы из прошлой статьи:

```c
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#ifdef __unix__
  #include <sys/stat.h>
  #include <fcntl.h>
  #include <unistd.h>
#elif defined _WIN32
  #include <windows.h>
#endif

// если выбрана домашняя папка пользователя
// устанавливаем пути в зависимости от ОС
void getHomeDirectory(char* dirname)
{
  #ifdef __unix__
    sprintf(dirname, "%s%s", getenv("HOME"), "/newdir/");
  #elif defined _WIN32
    sprintf(dirname, "%s%s%s", getenv("HOMEDRIVE"), getenv("HOMEPATH"), "\newdir\");
  #endif
}
// если выбрана текущая папка приложения
// устанавливаем пути в зависимости от ОС
void getCurrentDirectory(char* dirname)
{
  #ifdef __unix__
    strcpy(dirname, "newdir/");
  #elif defined _WIN32
    strcpy(dirname, "newdir\");
  #endif
}
// определение пути к новой папке
void getDirectoryName(char* dirname)
{
  #ifdef HOME_DIR
    getHomeDirectory(dirname);
  #elif defined CURRENT_DIR
    getCurrentDirectory(dirname);
  #endif
}
// создание новой папки в зависимости от определенной ОС
void createNewDirectory(char* dirname)
{
  #ifdef __unix__
    mkdir(dirname,S_IRWXU);
  #elif defined _WIN32
    CreateDirectory (dirname, NULL);
  #endif
}

int main(void)
{
  char dirname[60];
  char filename[60];
  char* text = "Hello enoobis.ru";
  getDirectoryName(dirname);    // получаем путь к папке вне зависимости от ОС
  createNewDirectory(dirname); // создание папки
  sprintf(filename, "%s%s", dirname, "newfile");
  FILE* f = fopen(filename, "w+");
  fwrite(text, 1, strlen(text), f); // запись текста в новый файл
  fclose(f);
  return 0;
}
```

Данная программа записывает в файл некоторый текст вне зависимости от операционной системы. В зависимости от установки констант HOME_DIR/CURRENT_DIR мы устанавливаем в качестве каталога для записи в файл либо домашнюю папку пользователя, либо текщий каталог. Однако в зависимости от операционной системы пути к каталогам будут отличаться. И чтобы определить текущую систему, проверяем константы `__unix__` и `_WIN32`.

Здесь работа с вариантами вынесена в отдельные функции, что упрощает поддержку программы. Тем не менее файл программы по прежнему работает с платформо-специфичным кодом, и платформо-зависимыая и платформо-независимая логика смешиваются в одном файле. Кроме того, платформо-зависимые функции могут потребоваться в других частях кодовой базы, что потребует их повторной реализации.

Решением данной проблемы может быть определение отдельного API для работы с платформо-зависимым кодом. В заголовочных файлах определяются только независимые от платформы функции. Эти функции вызываются клиентом-внешний кодом. А в реализацию функций помещается платформо-зависимый код с проверкой платформы с помощью **#ifdef**. То есть создается уровень абстракции, через который внешний код обращается к функциям и не знает, что они скрывают платформо-зависимую реализацию. В общем виде это выглядит следующим образом:

```c
/* Код someFeature.h - API с прототипами платформо-независимых функций */
void someFeature();

/* Код someFeature.c - реализация API с использованием платформо-зависимой логики */
void someFeature()
{
  #ifdef PLATFORM_A
    performFeaturePlatformA();
  #elif defined PLATFORM_B
    performFeaturePlatformB();
  #endif
}

/* Клиент обращается к платформо-независимым функциям API */
#include "someFeature.h"

int main(void)
{
  someFeature();
  return 0;
}
```

Итак, изменим программу, выделив код, который работает с вариантами в отдельные файлы. Сначала определим файл **directoryNames.h** с API для получения путь к папкам:

```c
